window.GLOSSARY=[{"ch": "ch01", "t": "细胞学说", "en": "cell theory", "d": "1838–1858 年 Schleiden、Schwann 提出、Virchow 补充：所有生物由一个或多个细胞构成；细胞是结构与功能的基本单位；细胞来自已有细胞的分裂。"}, {"ch": "ch01", "t": "原核细胞", "en": "prokaryotic cell", "d": "无核膜、无核仁、只有拟核，无膜被细胞器和细胞骨架，DNA 环状裸露。细菌、古细菌属之。"}, {"ch": "ch01", "t": "真核细胞", "en": "eukaryotic cell", "d": "有核膜包被的细胞核，有多种膜被细胞器和细胞骨架，DNA 与组蛋白结合成染色体。"}, {"ch": "ch01", "t": "拟核", "en": "nucleoid", "d": "原核细胞中 DNA 集中、无膜包被的区域。"}, {"ch": "ch01", "t": "支原体", "en": "Mycoplasma", "d": "已知最小、最简单的原核细胞，直径 0.1–0.3μm，也是唯一没有细胞壁的原核细胞。"}, {"ch": "ch01", "t": "古细菌", "en": "archaea", "d": "兼有原核与真核特征及独有特征的一类生物，代表第三界；常生存在极端环境。"}, {"ch": "ch01", "t": "模式生物", "en": "model organism", "d": "在进化上高度保守、便于遗传操作，用于研究生命普遍规律的代表性物种，如大肠杆菌、酵母、拟南芥、线虫、果蝇、斑马鱼、小鼠。"}, {"ch": "ch01", "t": "表面积/体积比", "en": "surface-to-volume ratio", "d": "细胞体积越大，相对表面积越小，物质交换效率越低，是限制细胞大小的主要因素。"}, {"ch": "ch01", "t": "原生质", "en": "protoplasm", "d": "1861 年 Max Schultze 提出的细胞学说内容，指细胞中具有“肉样质”的弹性胶状物质。"}, {"ch": "ch01", "t": "鞭毛蛋白", "en": "flagellin", "d": "组成原核细胞鞭毛的单一蛋白；真核鞭毛则由微管蛋白(tubulin)构成“9+2”结构。"}, {"ch": "ch02", "t": "流动镶嵌模型", "en": "fluid mosaic model", "d": "1972 年 Singer 与 Nicolson 提出：膜脂构成流动的脂双层，膜蛋白镶嵌其中，膜具有流动性和不对称性。"}, {"ch": "ch02", "t": "甘油磷脂", "en": "glycerophospholipid", "d": "膜脂的基本成分，占膜脂 50% 以上，由甘油骨架、两条脂肪酸尾和磷酸基团头部组成，构成脂双层骨架。"}, {"ch": "ch02", "t": "鞘脂", "en": "sphingolipid", "d": "以鞘氨醇为骨架的膜脂，包括鞘磷脂和糖脂，富集于脂筏。"}, {"ch": "ch02", "t": "胆固醇", "en": "cholesterol", "d": "膜脂之一，嵌在磷脂之间，双向调节膜流动性；自身不能形成脂双层。"}, {"ch": "ch02", "t": "脂筏", "en": "lipid raft", "d": "膜上富含胆固醇与鞘脂的有序微区，聚集特定蛋白，参与信号转导和物质运输。"}, {"ch": "ch02", "t": "脂质体", "en": "liposome", "d": "磷脂在水溶液中自发形成的封闭双层囊泡，可包裹药物/基因用于递送。"}, {"ch": "ch02", "t": "两亲性分子", "en": "amphipathic molecule", "d": "同时含亲水基团和疏水基团的分子；磷脂即为典型两亲性分子。"}, {"ch": "ch02", "t": "膜脂不对称", "en": "membrane lipid asymmetry", "d": "膜脂在脂双层内外两层的分布不同：PC、SM 多在外侧，PS、PE 多在胞质侧。"}, {"ch": "ch02", "t": "去垢剂", "en": "detergent", "d": "能插入膜、破坏疏水作用从而溶解膜蛋白的两亲性试剂，如 SDS、Triton X-100。"}, {"ch": "ch02", "t": "整合膜蛋白", "en": "integral membrane protein", "d": "嵌入脂双层疏水区、需去垢剂才能分离的膜蛋白。"}, {"ch": "ch02", "t": "外周膜蛋白", "en": "peripheral membrane protein", "d": "靠静电或氢键松散结合在膜表面，用高盐或极端 pH 即可洗脱。"}, {"ch": "ch02", "t": "脂锚定蛋白", "en": "lipid-anchored protein", "d": "通过共价连接的脂质锚(GPI、脂肪酸链、异戊二烯基)附着在膜上的蛋白。"}, {"ch": "ch02", "t": "GPI 锚", "en": "GPI anchor", "d": "糖基磷脂酰肌醇锚，把蛋白锚定在质膜外侧。"}, {"ch": "ch02", "t": "血影蛋白", "en": "spectrin", "d": "红细胞膜骨架的主要蛋白，四聚体连成网络，维持红细胞形态和弹性。"}, {"ch": "ch02", "t": "膜骨架", "en": "membrane skeleton", "d": "紧贴质膜胞质侧的蛋白网络，维持细胞形态、限制膜蛋白运动。"}, {"ch": "ch02", "t": "荧光漂白恢复", "en": "FRAP", "d": "用激光漂白局部荧光后观察荧光恢复速度，用于测定膜蛋白/膜脂的流动性。"}, {"ch": "ch02", "t": "相变温度", "en": "phase transition temperature", "d": "膜脂由液晶态转变为凝胶态的温度；低于此温度流动性降低。"}, {"ch": "ch02", "t": "被动运输", "en": "passive transport", "d": "顺浓度梯度、不消耗能量的跨膜运输，包括简单扩散和易化扩散。"}, {"ch": "ch02", "t": "简单扩散", "en": "simple diffusion", "d": "小分子直接穿过脂双层的被动运输，如 O₂、CO₂、水。"}, {"ch": "ch02", "t": "易化扩散", "en": "facilitated diffusion", "d": "借助载体或通道蛋白、顺浓度梯度、不耗能的运输。"}, {"ch": "ch02", "t": "通道蛋白", "en": "channel protein", "d": "形成亲水孔道、不与被转运物结合、快速被动运输的膜蛋白。"}, {"ch": "ch02", "t": "载体蛋白", "en": "carrier protein", "d": "与被转运物结合、发生构象变化来转运物质的膜蛋白，速度较慢、可饱和。"}, {"ch": "ch02", "t": "门控", "en": "gating", "d": "通道蛋白的开放受电压、配体或机械力调控。"}, {"ch": "ch02", "t": "葡萄糖载体", "en": "GLUT", "d": "介导葡萄糖易化扩散的载体家族，如 GLUT1、GLUT2、GLUT4(胰岛素调节)。"}, {"ch": "ch02", "t": "水通道蛋白", "en": "aquaporin (AQP)", "d": "介导水快速跨膜运输的通道蛋白；AQP1 发现获 2003 年诺贝尔化学奖。"}, {"ch": "ch02", "t": "离子泵", "en": "ion pump", "d": "逆浓度梯度、消耗 ATP 转运离子的主动运输蛋白。"}, {"ch": "ch02", "t": "钠钾泵", "en": "Na⁺/K⁺-ATPase", "d": "每水解 1 个 ATP 泵出 3 个 Na⁺、泵入 2 个 K⁺，维持离子梯度、膜电位和渗透平衡。"}, {"ch": "ch02", "t": "协同运输", "en": "cotransport", "d": "一种物质顺浓度梯度驱动另一种物质逆浓度梯度运输，属继发性主动运输。"}, {"ch": "ch02", "t": "静息电位", "en": "resting potential", "d": "静息时膜对 K⁺ 通透性大于 Na⁺、K⁺ 外流形成的膜内外电位差，约 -70mV。"}, {"ch": "ch02", "t": "动作电位", "en": "action potential", "d": "神经/肌肉细胞受刺激时膜电位的快速逆转：去极化→反极化→复极化→超极化。"}, {"ch": "ch02", "t": "主动运输", "en": "active transport", "d": "逆浓度梯度、需消耗能量的跨膜运输。"}, {"ch": "ch02", "t": "钾通道选择性", "en": "K⁺ channel selectivity", "d": "K⁺ 通道的选择性滤器使 K⁺ 脱水后通过，而排斥水合半径更大的 Na⁺。"}, {"ch": "ch03", "t": "内膜系统", "en": "endomembrane system", "d": "细胞质中由单层膜包被、结构与功能相互关联的细胞器群，包括 ER、Golgi、溶酶体、胞内体、分泌泡等。"}, {"ch": "ch03", "t": "分室化", "en": "compartmentalization", "d": "膜把细胞分隔成不同区室，各具独特酶系和内环境，使代谢高效、有序、互不干扰。"}, {"ch": "ch03", "t": "微粒体", "en": "microsome", "d": "细胞匀浆时内质网膜破碎后重新封闭成的囊泡，保留 ER 酶系。"}, {"ch": "ch03", "t": "差速离心", "en": "differential centrifugation", "d": "利用不同细胞器大小/密度差异，逐级提高离心力分批沉淀来分离细胞器。"}, {"ch": "ch03", "t": "密度梯度离心", "en": "density gradient centrifugation", "d": "在密度梯度介质中离心，使不同密度的细胞器停留在不同位置，用于精细分离。"}, {"ch": "ch03", "t": "放射自显影", "en": "autoradiography", "d": "用放射性同位素标记分子，通过感光显影定位其在细胞内的分布。"}, {"ch": "ch03", "t": "脉冲追踪", "en": "pulse-chase", "d": "先用放射性标记(脉冲)、再换无标记培养基(追踪)，观察标记物在细胞内转移路径，如分泌蛋白 rER→Golgi→分泌泡。"}, {"ch": "ch03", "t": "绿色荧光蛋白", "en": "GFP", "d": "可发绿色荧光的蛋白，与目标蛋白融合后可实时观察其在活细胞中的定位和运动。"}, {"ch": "ch03", "t": "粗面内质网", "en": "rough ER (rER)", "d": "表面附着核糖体，合成分泌蛋白和膜蛋白，并进行 N-糖基化、二硫键形成。"}, {"ch": "ch03", "t": "光面内质网", "en": "smooth ER (sER)", "d": "无核糖体，功能为合成脂质、解毒(细胞色素 P450)、储存 Ca²⁺。"}, {"ch": "ch03", "t": "肌质网", "en": "sarcoplasmic reticulum", "d": "肌细胞中特化的 sER，储存 Ca²⁺，控制肌肉收缩。"}, {"ch": "ch03", "t": "细胞色素 P450", "en": "cytochrome P450", "d": "sER 膜上的氧化酶，通过羟化反应解毒药物和毒物。"}, {"ch": "ch03", "t": "信号肽", "en": "signal peptide", "d": "位于分泌蛋白 N 端、约 16–26 个氨基酸的疏水序列，引导核糖体到 ER，进入 ER 腔后被切除。"}, {"ch": "ch03", "t": "信号斑", "en": "signal patch", "d": "肽链折叠后在表面形成的三维结构信号(非连续序列)，如溶酶体酶被识别加 M6P 的信号。"}, {"ch": "ch03", "t": "导肽", "en": "presequence", "d": "线粒体蛋白 N 端的引导序列，引导前体蛋白进入线粒体后被切除。"}, {"ch": "ch03", "t": "转运肽", "en": "transit peptide", "d": "叶绿体蛋白 N 端的引导序列，引导蛋白进入叶绿体后被切除。"}, {"ch": "ch03", "t": "核定位信号", "en": "NLS", "d": "亲核蛋白中一段短氨基酸序列，引导蛋白经核孔进入细胞核，不被切除。"}, {"ch": "ch03", "t": "信号识别颗粒", "en": "SRP", "d": "由 6 种多肽和 1 个 7S RNA 组成的复合体，识别信号肽并使翻译暂停，把核糖体带到 ER 膜。"}, {"ch": "ch03", "t": "SRP 受体", "en": "SRP receptor", "d": "rER 膜上由 α、β 亚基组成的受体，结合 SRP 使核糖体停泊到膜上。"}, {"ch": "ch03", "t": "易位子", "en": "translocon", "d": "rER 膜上的蛋白质通道，核心为 Sec61 复合体，介导新生肽链进入 ER 腔。"}, {"ch": "ch03", "t": "共翻译转运", "en": "co-translational translocation", "d": "肽链边翻译边经易位子进入 ER 的转运方式。"}, {"ch": "ch03", "t": "翻译后转运", "en": "post-translational translocation", "d": "蛋白在胞质合成完成后，再转运进入线粒体、叶绿体、过氧化物酶体等。"}, {"ch": "ch03", "t": "起始转移序列", "en": "start-transfer sequence", "d": "既引导核糖体到膜上、又作为跨膜起始信号使肽链穿入 ER 腔的信号序列。"}, {"ch": "ch03", "t": "停止转移序列", "en": "stop-transfer sequence", "d": "约 20 个氨基酸的疏水序列，使肽链停止穿膜并锚定在膜上。"}, {"ch": "ch03", "t": "跨膜拓扑", "en": "transmembrane topology", "d": "跨膜蛋白的穿膜次数及 N/C 端朝向，由起始/停止转移序列的数目和位置决定。"}, {"ch": "ch03", "t": "N-连接糖基化", "en": "N-linked glycosylation", "d": "在 rER 中把糖链连到 Asn 残基酰胺氮上的糖基化，供体是磷酸多萜醇。"}, {"ch": "ch03", "t": "O-连接糖基化", "en": "O-linked glycosylation", "d": "在高尔基体把糖链连到 Ser/Thr 羟基氧上的糖基化。"}, {"ch": "ch03", "t": "磷酸多萜醇", "en": "dolichol phosphate", "d": "内质网膜上的脂质载体，先组装寡糖前体再转移给新生肽链。"}, {"ch": "ch03", "t": "二硫键", "en": "disulfide bond", "d": "两个 Cys 之间形成的 S–S 键，在 ER 腔内形成，稳定蛋白质三维结构。"}, {"ch": "ch03", "t": "蛋白二硫键异构酶", "en": "PDI", "d": "ER 腔中的酶，催化二硫键的形成、重排和还原，帮助蛋白折叠。"}, {"ch": "ch03", "t": "Bip", "en": "Bip", "d": "ER 腔中的分子伴侣(Hsp70 家族)，结合新生肽链疏水区，帮助折叠并参与质量监控。"}, {"ch": "ch03", "t": "分子伴侣", "en": "molecular chaperone", "d": "帮助蛋白折叠、组装、转运，但不构成最终产物的蛋白。"}, {"ch": "ch03", "t": "蛋白质质量监控", "en": "protein quality control", "d": "ER 检查蛋白折叠是否正确：正确的放行去高尔基体，错误的滞留、重折叠或降解。"}, {"ch": "ch03", "t": "未折叠蛋白反应", "en": "UPR", "d": "ER 中未折叠蛋白积累时触发的信号反应，增加伴侣表达、减少蛋白合成。"}, {"ch": "ch03", "t": "ERAD", "en": "ERAD", "d": "内质网相关降解：错误折叠蛋白经 Sec61 逆向易位到胞质，泛素化后被蛋白酶体降解。"}, {"ch": "ch03", "t": "泛素", "en": "ubiquitin", "d": "由 76 个氨基酸组成的小蛋白，多个连成多聚泛素链作为蛋白降解信号。"}, {"ch": "ch03", "t": "泛素化", "en": "ubiquitination", "d": "在 E1、E2、E3 三种酶催化下把泛素共价连接到靶蛋白 Lys 上的过程，耗 ATP。"}, {"ch": "ch03", "t": "蛋白酶体", "en": "proteasome", "d": "26S 蛋白酶体＝20S 催化核心(α7β7β7α7)＋2 个 19S 调节帽，识别多聚泛素链并降解蛋白。"}, {"ch": "ch03", "t": "高尔基体极性", "en": "Golgi polarity", "d": "高尔基体分顺面(CGN)、中间膜囊、反面(TGN)，各区酶和功能不同。"}, {"ch": "ch03", "t": "顺面高尔基网络", "en": "CGN", "d": "高尔基体的顺面(入口)区，接收 ER 小泡并回收 ER 驻留蛋白。"}, {"ch": "ch03", "t": "反面高尔基网络", "en": "TGN", "d": "高尔基体的反面(出口)区，是蛋白质分选的中心。"}, {"ch": "ch03", "t": "蛋白聚糖", "en": "proteoglycan", "d": "核心蛋白上连接多条糖胺聚糖链的糖蛋白，在高尔基体组装后分泌到细胞外基质。"}, {"ch": "ch03", "t": "溶酶体", "en": "lysosome", "d": "单层膜围绕、含多种酸性水解酶的细胞器，最适 pH≈5，是细胞内消化的主要场所。"}, {"ch": "ch03", "t": "初级溶酶体", "en": "primary lysosome", "d": "新形成、只含酸性水解酶、尚未进行消化的溶酶体。"}, {"ch": "ch03", "t": "次级溶酶体", "en": "secondary lysosome", "d": "正在消化底物的溶酶体，包括自噬溶酶体和异噬溶酶体。"}, {"ch": "ch03", "t": "自噬", "en": "autophagy", "d": "细胞把自身受损细胞器或生物大分子包裹成自噬体，再与溶酶体融合降解。"}, {"ch": "ch03", "t": "异噬", "en": "heterophagy", "d": "溶酶体消化外源物质(如细菌、衰老红细胞)的过程。"}, {"ch": "ch03", "t": "酸性磷酸酶", "en": "acid phosphatase", "d": "溶酶体的标志酶，最适 pH 偏酸。"}, {"ch": "ch03", "t": "6-磷酸甘露糖", "en": "M6P", "d": "溶酶体酶在高尔基体获得的标志，被 M6P 受体识别并分选到溶酶体。"}, {"ch": "ch03", "t": "M6P 受体", "en": "M6P receptor", "d": "在 TGN 识别并结合 M6P 标志的受体，把溶酶体酶分选入转运小泡，可循环使用。"}, {"ch": "ch03", "t": "I-细胞病", "en": "I-cell disease", "d": "因 GlcNAc 磷酸转移酶缺陷、溶酶体酶缺 M6P，酶被分泌到血液而溶酶体缺酶的遗传病。"}, {"ch": "ch03", "t": "KDEL", "en": "KDEL", "d": "ER 驻留蛋白 C 端的回收信号(Lys-Asp-Glu-Leu)，逃逸到高尔基体后被受体回收回 ER。"}, {"ch": "ch04", "t": "囊泡运输", "en": "vesicular transport", "d": "以内膜系统运输小泡为载体，在细胞器之间及与质膜之间运输蛋白质的方式。"}, {"ch": "ch04", "t": "跨膜运输", "en": "transport across membranes", "d": "蛋白由导肽/转运肽引导，直接跨膜进入线粒体、叶绿体、过氧化物酶体的运输方式。"}, {"ch": "ch04", "t": "核孔运输", "en": "transport through nuclear pores", "d": "大分子经核孔复合体的选择性、主动运输进出细胞核。"}, {"ch": "ch04", "t": "包被小泡", "en": "coated vesicle", "d": "外被蛋白组装成包被的运输小泡，主要有网格蛋白小泡、COPII、COPI。"}, {"ch": "ch04", "t": "网格蛋白", "en": "clathrin", "d": "由 3 条重链和 3 条轻链组成三脚复合体，组装成网格包被，介导内吞和 TGN 出发的运输。"}, {"ch": "ch04", "t": "三脚复合体", "en": "triskelion", "d": "网格蛋白的基本结构单位，由 3 条重链和 3 条轻链组成。"}, {"ch": "ch04", "t": "衔接蛋白", "en": "adaptor protein (AP)", "d": "位于网格蛋白与货物受体之间，负责把货物选择性地装入有被小泡。"}, {"ch": "ch04", "t": "发动蛋白", "en": "dynamin", "d": "小 G 蛋白，在胞吞小泡颈部形成环并水解 GTP 收缩，把有被小泡从膜上掐断。"}, {"ch": "ch04", "t": "受体介导胞吞", "en": "receptor-mediated endocytosis", "d": "细胞外配体先与质膜受体结合，再经网格蛋白有被小窝内吞入胞的过程。"}, {"ch": "ch04", "t": "低密度脂蛋白", "en": "LDL", "d": "血液中运输胆固醇的脂蛋白，核心为胆固醇酯、外壳为磷脂和 apoB-100。"}, {"ch": "ch04", "t": "载脂蛋白 B-100", "en": "apoB-100", "d": "LDL 表面的蛋白，是 LDL 受体的配体。"}, {"ch": "ch04", "t": "转铁蛋白", "en": "transferrin", "d": "结合并运输 Fe³⁺ 的血浆蛋白，经受体介导胞吞把铁送入细胞，载体可循环使用。"}, {"ch": "ch04", "t": "家族性高胆固醇血症", "en": "familial hypercholesterolemia", "d": "LDL 受体基因缺失或受体无功能，导致血胆固醇升高、动脉粥样硬化的遗传病。"}, {"ch": "ch04", "t": "COPII", "en": "COPII", "d": "负责 ER→Golgi 顺行运输的有被小泡，由 Sec23/24 与 Sec13/31 组成，装配依赖 Sar1。"}, {"ch": "ch04", "t": "COPI", "en": "COPI", "d": "负责 Golgi→ER 逆行运输的有被小泡，捕获逃逸蛋白回 ER，装配依赖 ARF。"}, {"ch": "ch04", "t": "Sar1", "en": "Sar1", "d": "启动 COPII 装配的小 G 蛋白。"}, {"ch": "ch04", "t": "ARF", "en": "ARF", "d": "参与 COPI 和网格蛋白小泡装配的小 G 蛋白。"}, {"ch": "ch04", "t": "回收信号", "en": "retrieval signal", "d": "ER 驻留蛋白 C 端的序列(如 KDEL/KKXX)，逃逸后经 COPI 小泡被回收回 ER。"}, {"ch": "ch04", "t": "Rab 蛋白", "en": "Rab", "d": "GTP 酶超家族的单体开关蛋白，高度选择性地分布在不同膜上，控制小泡的识别、锚定与停靠。"}, {"ch": "ch04", "t": "鸟苷酸交换因子", "en": "GEF", "d": "催化小 G 蛋白 GDP→GTP 活化的小 G 蛋白调节因子。"}, {"ch": "ch04", "t": "GTP 酶活化蛋白", "en": "GAP", "d": "促使小 G 蛋白水解 GTP 而失活的调节因子。"}, {"ch": "ch04", "t": "GDI", "en": "GDI", "d": "鸟苷酸解离抑制蛋白，把 Rab-GDP 从膜上提取、运送到供体膜。"}, {"ch": "ch04", "t": "SNARE", "en": "SNARE", "d": "介导运输小泡与靶膜融合的蛋白家族，分 v-SNARE(小泡)与 t-SNARE(靶膜)。"}, {"ch": "ch04", "t": "v-SNARE", "en": "v-SNARE", "d": "位于运输小泡上的 SNARE，如 VAMP。"}, {"ch": "ch04", "t": "t-SNARE", "en": "t-SNARE", "d": "位于靶膜上的 SNARE，如 Syntaxin 与 SNAP-25。"}, {"ch": "ch04", "t": "VAMP", "en": "VAMP", "d": "小泡上的 v-SNARE，与靶膜 SNARE 配对介导融合。"}, {"ch": "ch04", "t": "Syntaxin", "en": "Syntaxin", "d": "靶膜上的 t-SNARE。"}, {"ch": "ch04", "t": "SNAP-25", "en": "SNAP-25", "d": "靶膜上的 t-SNARE，与 Syntaxin、VAMP 组成 SNARE 复合体。"}, {"ch": "ch04", "t": "NSF", "en": "NSF", "d": "N-乙基顺丁烯二酰亚胺敏感融合蛋白，与 α-SNAP 一起、由 ATP 水解驱动解离 SNARE 复合体。"}, {"ch": "ch04", "t": "α-SNAP", "en": "α-SNAP", "d": "可溶性 NSF 附着蛋白，协助 NSF 结合并解离 SNARE 复合体。"}, {"ch": "ch04", "t": "停靠", "en": "docking", "d": "Rab-GTP 与效应蛋白把运输小泡识别并锚定在正确靶膜上的过程。"}, {"ch": "ch04", "t": "膜融合", "en": "membrane fusion", "d": "v-SNARE 与 t-SNARE 配对形成复合体，拉近两膜并使之融合。"}, {"ch": "ch05", "t": "前体蛋白", "en": "precursor protein", "d": "在胞质合成、含 N 端导肽/转运肽的蛋白，需转运入线粒体、叶绿体等后成熟。"}, {"ch": "ch05", "t": "TOM 复合体", "en": "TOM complex", "d": "线粒体外膜上的转运器，由受体和转位通道组成，接收胞质前体蛋白。"}, {"ch": "ch05", "t": "TIM 复合体", "en": "TIM complex", "d": "线粒体内膜上的转运器，TIM23 把蛋白送入基质，TIM22 插入内膜载体蛋白。"}, {"ch": "ch05", "t": "SAM 复合体", "en": "SAM complex", "d": "线粒体外膜上把外膜蛋白插入外膜的转运器。"}, {"ch": "ch05", "t": "OXA 复合体", "en": "OXA complex", "d": "线粒体内膜上把内膜蛋白插入内膜的转运器。"}, {"ch": "ch05", "t": "接触点", "en": "contact site", "d": "线粒体内外膜紧密贴近的区域，前体蛋白经此从胞质进入基质。"}, {"ch": "ch05", "t": "Hsp70", "en": "Hsp70", "d": "热激蛋白/分子伴侣，在胞质维持前体蛋白解析叠，在基质以 ATP 驱动其转位。"}, {"ch": "ch05", "t": "核被膜", "en": "nuclear envelope", "d": "由内外两层核膜组成的结构，把细胞核与胞质分开。"}, {"ch": "ch05", "t": "核孔复合体", "en": "NPC", "d": "核被膜上由胞质环、核质环、辐、中央运输蛋白组成的通道，介导核质物质交换。"}, {"ch": "ch05", "t": "胞质环", "en": "cytoplasmic ring", "d": "核孔复合体胞质面的一环，有 8 条短纤维伸向胞质。"}, {"ch": "ch05", "t": "核质环", "en": "nuclear ring", "d": "核孔复合体核质面的一环，有 8 条长纤维伸向核内并形成核篮。"}, {"ch": "ch05", "t": "核篮", "en": "nuclear basket", "d": "核质环 8 条长纤维末端形成的直径约 60nm 的小环，形似鱼笼(fish-trap)。"}, {"ch": "ch05", "t": "辐", "en": "spoke", "d": "核孔边缘伸向中心的结构，呈辐射状八重对称。"}, {"ch": "ch05", "t": "中央运输蛋白", "en": "central transporter", "d": "位于核孔中心，是核质交换的主动运输载体。"}, {"ch": "ch05", "t": "核纤层", "en": "nuclear lamina", "d": "紧贴内核膜的中间纤维网络，支撑核膜、维持核形态。"}, {"ch": "ch05", "t": "核输出信号", "en": "NES", "d": "核内物质输出细胞核的信号，被 exportin 识别。"}, {"ch": "ch05", "t": "输入蛋白", "en": "importin", "d": "胞质中识别 NLS 的受体，介导亲核蛋白入核。"}, {"ch": "ch05", "t": "输出蛋白", "en": "exportin", "d": "核内识别 NES 的受体，与 Ran-GTP 一起介导货物出核。"}, {"ch": "ch05", "t": "Ran", "en": "Ran", "d": "调控核质运输的关键 GTP 酶；核内 Ran-GTP 高，胞质 Ran-GDP 高。"}, {"ch": "ch05", "t": "Ran-GEF", "en": "RCC1", "d": "核内的 Ran 鸟苷酸交换因子，催化 Ran-GDP→Ran-GTP。"}, {"ch": "ch05", "t": "Ran-GAP", "en": "Ran-GAP", "d": "胞质中的 Ran GTP 酶活化蛋白，使 Ran-GTP 水解为 Ran-GDP。"}, {"ch": "ch05", "t": "过氧化物酶体", "en": "peroxisome", "d": "单层膜围绕的细胞器，又称微体，含氧化酶和过氧化氢酶，分解脂肪酸、解毒。"}, {"ch": "ch05", "t": "微体", "en": "microbody", "d": "过氧化物酶体的别称。"}, {"ch": "ch05", "t": "PTS1", "en": "PTS1", "d": "过氧化物酶体蛋白的引导信号之一，多数为 C 端 SKL 序列。"}, {"ch": "ch05", "t": "PTS2", "en": "PTS2", "d": "过氧化物酶体蛋白的 N 端引导信号。"}, {"ch": "ch05", "t": "Pex 蛋白", "en": "Pex3/Pex16", "d": "参与过氧化物酶体膜形成和蛋白导入的膜蛋白，部分来自内质网。"}, {"ch": "ch05", "t": "过氧化氢酶", "en": "catalase", "d": "过氧化物酶体中分解 H₂O₂ 的酶。"}, {"ch": "ch01", "t": "细胞工程", "en": "", "d": "细胞工程是指在细胞水平的生物工程中，应用细胞培养、细胞分化的定向诱导、细胞融 合和显微注射等技术，使细胞获得新的性状以及创造新的生物品种的现代生物技术。"}, {"ch": "ch01", "t": "细胞生物学", "en": "", "d": "细胞生物学是指从细胞的显微结构、超微结构和分子结构的各级水平研究细胞的结构与 功能的关系，探索细胞生长、发育、分化、繁殖、遗传、变异、代谢、衰亡及进化等各种生 命现象规律的科学。"}, {"ch": "ch01", "t": "细胞社会学", "en": "", "d": "细胞社会学是研究一个细胞群中细胞与细胞间的相互关系的科学，主要内容包括不同细 胞或相同细胞的相互识别、细胞的聚集与黏连、细胞间的物质和信息交流、细胞与细胞外间 质的相互影响，甚至还包括细胞群中组织分化模式的形成等。"}, {"ch": "ch02", "t": "中心质", "en": "", "d": "中心质是指在光镜下观察到的蓝藻细胞中央部位较周围原生质明亮，遗传物质 DNA 所 在部位，它相当于细菌的核区。"}, {"ch": "ch02", "t": "中膜体", "en": "", "d": "中膜体是由细胞膜内陷形成的，每个细胞内有一个或数个中膜体，其形状差异很大，革 兰阳性菌中常见，可能起 DNA 复制支点作用。"}, {"ch": "ch02", "t": "内生孢子", "en": "", "d": "内生孢子是指当细菌处于不利的环境，或营养缺乏时，细胞内的重要物质，特别是 DNA， 集聚在细胞的一端，形成一种含水量较丰富、外被厚壁、具有很强的折光性、不易染色的致 密体，保证细菌能在恶劣的条件下依然存活，对不良环境有强抵抗力的休眠体。"}, {"ch": "ch02", "t": "质粒", "en": "", "d": "质粒是指独立于细胞染色体外的裸露的双链环状 DNA 分子，可进行单独复制的辅助遗 传单位。一般情况下，质粒对宿主的生存不是必需的，但质粒的某些基因编码产物，可以弥 补细菌本身功能的不足，从而有利于细菌的生存。质粒是基因工程的重要载体。"}, {"ch": "ch02", "t": "类核", "en": "", "d": "类核是指在原核细胞中一种由环状 DNA 分子盘绕且由其他密度较低的物质包绕的区域。 核区可呈现各种形状，一个细胞中可以有多个核区。"}, {"ch": "ch02", "t": "基因组", "en": "", "d": "基因组是指细胞或生物体中，一套完整单倍染色体组中总的遗传信息。基因组大小通常 随物种的复杂性而增加。"}, {"ch": "ch02", "t": "类病毒", "en": "", "d": "类病毒是指仅由一个有感染性的 RNA 构成的类似病毒的简单生命体。"}, {"ch": "ch02", "t": "朊病毒", "en": "", "d": "朊病毒是指仅由有感染性的蛋白质构成的生命体。"}, {"ch": "ch02", "t": "细胞融合", "en": "", "d": "细胞融合是指两个或多个细胞融合成一个双核或多核细胞的过程，常需对细胞进行预处 理或者借助某些化学物质和灭活病毒介导完成。如动物细胞融合一般要用灭活的病毒（如仙 台病毒）或化学物质（如 PEG）介导；植物细胞融合时，要先用酶去掉细胞壁。细胞融合 技术是单克隆抗体制备等的基础。"}, {"ch": "ch03", "t": "分辨率", "en": "", "d": "分辨率是指区分开两个质点间的最小距离。两个质点间的距离取决于光源波长、物镜镜 口角     和介质折射率。分辨率是衡量显微镜性能的重要参数。"}, {"ch": "ch03", "t": "激光共焦点扫描显微镜技术", "en": "", "d": "激光共焦点扫描显微镜技术是指是用激光作为荧光的激发光，首先通过显微装置对样品 的不同层面进行扫描获得二维荧光影像，再通过计算机软件对每一个图层的影像进行三维重 建，而获得细胞的三维图像的一种显微技术。每一个图层的二维影像都相对比较清晰，是因 为它采用了物镜和聚光镜共焦点的技术，使被选择的焦面发出的荧光聚焦成像，而焦面以外 的漫射光被小孔阻挡，不能达到检测器成像。"}, {"ch": "ch03", "t": "荧光共振能量转移", "en": "", "d": "荧光共振能量转移是指当供体发射的荧光与受体发色团分子的吸收光谱重叠，并且两个 探针的距离在 10nm 范围以内时，产生的一种能够用于检测活体中生物大分子纳米级距离和 纳米级距离变化的有力工具，可用于检测某一细胞中两个蛋白质分子是否存在直接的相互作 用。"}, {"ch": "ch03", "t": "负染色技术", "en": "", "d": "负染色技术是指用重金属盐对铺展在载网上的样品染色，吸去多余染料，干燥后，使样 品凹陷处铺上一层重金属盐，而凸出的地方没有染料沉积，从而出现负染效果的一种技术； 分辨率可达 1.5nm 左右。"}, {"ch": "ch03", "t": "冷冻蚀刻技术", "en": "", "d": "冷冻蚀刻技术是指首先用快速低温冷冻法将样品迅速冷冻；然后在低温下使相对脆弱部 位断裂，用铂、金等金属进行倾斜喷镀，再垂直于断面进行碳真空喷镀，形成一层连续的碳 膜；最后将样品本身消化，在电镜下观察碳膜和金属“铸型”的一种技术。主要用来观察膜断 裂面的蛋白质颗粒和膜表面结构，不需包埋和固定，能保持样品的真实结构。"}, {"ch": "ch03", "t": "原位杂交", "en": "", "d": "原位杂交是指用标记的核酸探针通过分子杂交（碱基互补配对）确定特殊核苷酸序列在 染色体上或在细胞中的位置的方法。"}, {"ch": "ch03", "t": "细胞培养", "en": "", "d": "细胞培养是指在无菌条件下，把动物或植物的细胞从有机体分离出来，在模拟体内的环 境中，给予营养物质，使细胞不断生长、繁殖或传代，借以观察细胞的生长、分裂以及细胞 的衰老、癌变、死亡等生命现象的技术。"}, {"ch": "ch03", "t": "接触抑制", "en": "", "d": "接触抑制是指细胞培养过程中出现的一种有趣现象。在培养开始后，分散的细胞悬液在 培养瓶中不久就会贴附在瓶壁上，原来呈圆形的细胞一经贴壁便会迅速铺展而变成多种形态， 随即细胞开始分裂，贴壁生长形成致密的单层细胞。当细胞分裂、生长到表面相互接触时， 就会停止增殖，维持相互接触的单层细胞状态直至衰老，这就是所谓的接触抑制。"}, {"ch": "ch03", "t": "非细胞体系", "en": "", "d": "非细胞体系是指包含有进行细胞内正常生物学过程所需的成分但不具有完整细胞结构的 体外实验反应体系。一般由活细胞经裂解破碎、超速离心除去某些成分后制备而来。非细胞 体系在研究探讨 DNA 复制、RNA 转录、蛋白质合成、核膜及染色质的组装等细胞内生命活 动的基本过程和机理方面具有重要应用价值。"}, {"ch": "ch03", "t": "印迹术", "en": "", "d": "印迹术是指通过电泳或毛细管作用将 DNA、RNA 或蛋白质转移到某种基膜（如 DBM 滤纸、硝酸纤维素膜或尼龙膜）上的过程。由于此类过程类似于把墨渍吸到吸墨纸上而称为 blotting，可译为“印渍术”。根据转移成分的不同，       印迹术分为 DNA 印迹术（Southern blotting）、 RNA 印迹术（Northern blotting）和蛋白质印迹术（Western blotting）、当用凝胶进行抗原抗 体反应，再进行印迹时，则为伊斯特尔印迹术（Eastern blotting）。"}, {"ch": "ch03", "t": "细胞系", "en": "", "d": "细胞系是指经过原代培养 10 代后少数存活能继续顺利地传 40～50 代次，并且仍保持原 来染色体的二倍体数量及接触抑制的行为的传代细胞，分为有限细胞系和永生细胞系。 细胞株是指通过选择法或克隆法从原代培养或细胞系中获得的具有特殊性质或标记物的细 胞培养物，即细胞株是通过单细胞分离培养和筛选由单细胞形成的细胞群。细胞株的特殊性 质或标记物必须在整个培养期间一直存在。"}, {"ch": "ch03", "t": "超微结构", "en": "", "d": "超微结构即亚显微结构，是指在电子显微镜下所观察到的细胞结构，如细胞核、线粒体、 高尔基体、中心体、核糖体、微管、微丝等细胞器的微细结构。这些细胞内的各种微细结构 在普通光学显微镜下不能分辨清楚，必须用分辨力更高的电子显微镜。"}, {"ch": "ch03", "t": "基因打靶", "en": "", "d": "基因打靶是指通过同源重组将外源基因定点整合入靶细胞基因组上某一确定的位点，达 到定点修饰改造染色体上某一基因的一项技术。基因打靶技术是一种定向改变生物活体遗传 信息的实验手段，通过对生物活体遗传信息的定向修饰包括基因灭活、点突变引入、缺失突 变、外源基因定位引入、染色体组大片段删除等，并使修饰后的遗传信息在生物活体内遗传， 表达突变的性状，从而可以研究基因功能等生命科学的重大问题，以及提供相关的疾病治疗、 新药筛选评价模型等。"}, {"ch": "ch03", "t": "基因敲除", "en": "", "d": "基因敲除是指通过基因工程的方法使目的基因功能丧失的人工定向突变技术。多用于各 种遗传疾病的研究，如研究特定基因的细胞生物学活性、研究发育调控的基因作用和确定信 号通路分子的上下游关系等。"}, {"ch": "ch04", "t": "细胞质膜", "en": "cell membrane", "d": "细胞质膜（cell membrane）是指围绕在细胞最外层，由磷脂双分子层与镶嵌蛋白质构成 的富有弹性的半透性膜，又称细胞膜，厚约 5～10nm。细胞质膜不仅是细胞结构的边界，使 细胞具有一个相对稳定的内环境，同时在细胞与环境之间进行物质、能量的交换，在信息传 递过程中也起着决定性的作用。"}, {"ch": "ch04", "t": "光脱色荧光恢复技术", "en": "fluorescence recovery after photobleaching", "d": "光脱色荧光恢复技术（fluorescence recovery after photobleaching）是指用荧光素标记膜 蛋白或膜脂，然后用激光束照射细胞表面某一区域，使被照射区的荧光逐渐变暗，停止照射 后，由于膜的流动性，变暗区域的亮度逐渐增加，最后恢复，根据荧光恢复的速度可推算出 膜蛋白或膜脂的扩散速率的一种技术。该技术是研究膜蛋白或膜脂流动性的基本试验技术之 一。"}, {"ch": "ch04", "t": "胞膜窟", "en": "caveolae", "d": "胞膜窟（caveolae）是指一种相对有序、结构相对稳定，直径 50～100nm 的质膜凹陷区。 胞膜窟在细胞的信息传递和物质运输中起重要作用。"}, {"ch": "ch05", "t": "协助扩散", "en": "facilitated diffusion", "d": "协助扩散（facilitated diffusion）是各种极性分子和无机离子，如糖、氨基酸、核苷酸以 及细胞代谢物等顺其浓度梯度或电化学梯度减小的方向的跨膜转运，该过程不需要细胞提供 能量，属于被动运输。"}, {"ch": "ch05", "t": "质子泵", "en": "", "d": "质子泵是指位于细胞质膜或细胞内膜上的一种能主动转运质子的特殊蛋白质。人体及动 物细胞中的质子泵可分成 3 种，一种与 Na -K 泵和 Ca2 泵结构类似，存在于质膜上，在转 ＋ ＋ ＋   运 H 的过程中发生磷酸化和去磷酸化，称 P 型质子泵；第二种存在于溶酶体膜上，在转运 ＋   H 的过程中不形成磷酸化的中间体，称 V 型质子泵；第三种则位于线粒体的内膜上，功能 ＋   较特殊．转运 H 时顺浓度梯度进行，同时将该过程释放的能量以合成 ATP 的方式储存起 ＋   来，换句话说，线粒体内膜上质子泵对 H＋的转运偶联了 ATP 合成反应（即磷酸化反应）。"}, {"ch": "ch05", "t": "组成型胞吐途径", "en": "constitutive exocytosispathway", "d": "组成型胞吐途径（constitutive exocytosispathway）是指在真核细胞中，由高尔基体反面 囊膜分泌的囊泡向质膜流动并与之融合的膜泡运输过程，呈连续分泌状态，完成质膜更新， 分泌胞外基质组分、营养或信号分子等功能。"}, {"ch": "ch05", "t": "调节型胞吐途径", "en": "regulated exocytosis pathway", "d": "调节型胞吐途径（regulated exocytosis pathway）是指在真核生物的一些特化细胞中，所 产生的分泌物储存在分泌泡内，当细胞在受到胞外刺激时，分泌泡与质膜融合并将内含物分 泌出细胞的胞吐作用方式。"}, {"ch": "ch05", "t": "配体门控通道", "en": "", "d": "配体门控通道是一种需要配体与特定受体结合后才能开启的闸门通道，属于离子通道的 一种，这种通道在多数情况下呈关闭状态，当受到某种化学信号物质（配体）的作用后才开 启形成跨膜的离子通道"}, {"ch": "ch05", "t": "电压门控通道", "en": "", "d": "电压门控通道是在细胞膜电位突然变化产生特定电压的条件下才能开启的离子通道。例 如，电压门控 Na 通道与 K 通道在膜静息电位（膜电荷为内负外正的极化状态）时呈关闭 ＋        ＋   状态，当膜去极化（极化状态减小）而使膜内外的电位差降低时，通道开放。"}, {"ch": "ch05", "t": "ABC 超家族", "en": "", "d": "ABC super family 的中文名称是 ABC 超家族。ABC 超家族是一类 ATP 驱动的膜转运蛋 白，利用 ATP 水解释放的能量将多肽及多种小分子物质进行跨膜转运。ABC 超家族包含有 几百种不同的转运蛋白，广泛分布于从细菌到人类的各种生物中，所有 ABC 蛋白一般含有 4 个核心结构域：两个跨膜结构域（T），形成运输分子的跨膜通道；两个胞质侧 ATP 结合 域（A），具有 ATP 酶活性。"}, {"ch": "ch05", "t": "受体介导的内吞作用", "en": "", "d": "受体介导的内吞作用是指细胞依靠细胞表面的受体特异性地摄取细胞外蛋白或其他化合 物的过程。其具有高度特异性，是通过细胞表面的受体与其相应的配体特异性的结合来实现 的。如细胞摄取胆固醇过程就是受体介导的胞吞作用。"}, {"ch": "ch06", "t": "内共生学说", "en": "endoeymbiosis theory", "d": "内共生学说（endoeymbiosis theory）是指认为线粒体和叶绿体分别起源于原始真核细胞 内共生的细菌和蓝藻的一种学说。线粒体来源于细菌，即细菌被真核生物吞噬后，在长期共 生过程中，通过演变，形成了线粒体。叶绿体来源于蓝藻，被原始真核细胞摄入胞内，在共 生关系中，形成了叶绿体。"}, {"ch": "ch06", "t": "非共生起源学说", "en": "aeymbiotic theory", "d": "非共生起源学说（aeymbiotic theory）是指认为真核细胞的前身是一个进化上比较高等 的好氧细菌，它比典型的原核细胞大，这样就要逐渐增加呼吸作用的膜表面的一种学说。开 始是通过细菌细胞膜的内陷，扩张和分化（形成的双层膜分别将基因组包围在其中），后形 成了线粒体、叶绿体和细胞核的雏形。"}, {"ch": "ch06", "t": "化学渗透学说", "en": "", "d": "化学渗透学说是由英国生物化学家 P．Mitchell 于 1961 年提出的用来解释氧化磷酸化偶 联机制的假说。该学说认为：在电子传递过程中，伴随着质子从线粒体内膜的里层向外层转 移，形成跨膜的氢离子梯度，这种势能为氧化磷酸化反应提供了动力，合成了 ATP。这一 学说具有大量的实验证明，得到公认并获得了 l978 年诺贝尔奖。化学渗透学说可以很好地 说明线粒体内膜中电子传递、质子电化学梯度建立、ADP 磷酸化的关系。"}, {"ch": "ch06", "t": "前质体", "en": "", "d": "前质体是质体的前身，仅由内膜和外膜构成，膜内是少量的基质和 DNA，但是没有 LHC 蛋白、叶绿素和电子传递系统。植物中的前质体随着在发育过程中所处的位置及接受光的多 少程度，分化成功能各异的质体。 质体是植物细胞中由双层膜包裹的一类细胞器的总称，这类细胞器都是由共同的前体（前质 体）分化发育而来，包括叶绿体、白色体、淀粉质体、有色体、蛋白质体、油质体等。"}, {"ch": "ch06", "t": "光反应", "en": "", "d": "光反应是通过叶绿素等光合色素分子吸收光能，并将光能转化为化学能，形成 ATP 和 NADPH 的过程。光反应包括光能吸收、电子传递、光合磷酸化三个主要步骤。光反应的场 所是类囊体。 暗反应是 CO2 固定反应，在这一反应中，叶绿体利用光反应产生的 ATP 和 NADPH 这两个 高能化合物分别作为能源和还原的动力将 CO2 固定，使之转变成葡萄糖，由于这一过程是 在黑暗条件下进行所以称为暗反应。暗反应开始于叶绿体基质，结束于细胞质基质。"}, {"ch": "ch06", "t": "生物氧化", "en": "cellular respiration", "d": "生物氧化又称细胞呼吸（cellular respiration），是指各类有机物质在细胞内进行氧化分 解，最终产生 CO2 和 H2O，同时释放能量（ATP）的过程。包括 TCA 循环、电子传递和氧 化磷酸化三个步骤，分别是在线粒体的不同部位进行的。"}, {"ch": "ch06", "t": "原初反应", "en": "", "d": "原初反应是指聚光色素分子吸收光量子传到反应中心进行光化学反应的物理过程，包括 光能的吸收、传递与转换。"}, {"ch": "ch06", "t": "电子传递链", "en": "", "d": "电子传递链是一系列电子载体按对电子亲和力逐渐升高的顺序组成的电子传递系统。所 有组成成分都嵌合于线粒体内膜或叶绿体类囊体膜或其他生物膜中，而且按顺序分段组成分 离的复合物，在复合物内各载体成分的物理排列也符合电子流动的方向。其中线粒体中的电 子传递链是伴随着营养物质的氧化放能，又称呼吸链。"}, {"ch": "ch06", "t": "循环式光合磷酸化", "en": "", "d": "循环式光合磷酸化是指 PSⅠ接受远红光后，产生电子经过 A0、A1、Fe-S 和 Fd，又传 给 Cyt b6f 和 PC 而流回到 PSⅠ，形成闭合回路的过程。电子循环流动，产生 H 梯度，从而 ＋   驱动 ATP 的形成。循环光合磷酸化由 PSⅠ单独完成，同时在其过程中只有 ATP 的产生， 不伴随 NADPH 的生成和 02 的释放."}, {"ch": "ch07", "t": "磷脂转换蛋白", "en": "phospholipid exchange proteins，PEP", "d": "磷脂转换蛋白（phospholipid exchange proteins，PEP）是一种水溶性的载体蛋白，其功 能是与磷脂结合，并在膜之间转移磷脂。"}, {"ch": "ch07", "t": "O-连接的糖基化", "en": "O-linked glycosylation", "d": "O-连接的糖基化（O-linked glycosylation）是指在内质网或高尔基体，由不同的糖基转 移酶催化，将一个一个单糖连接到丝氨酸、苏氨酸、羟赖氨酸或羟脯氨酸的羟基 O 原子上 的糖基化修饰方式。"}, {"ch": "ch07", "t": "残余小体", "en": "residual body", "d": "残余小体（residual body）是指次级溶酶体经过一段时间的消化后，被消化的小分子物 质被膜上的载体蛋白转运到细胞质基质中，而未被消化的物质残存在溶酶体中所形成的结构。"}, {"ch": "ch07", "t": "高尔基复合体", "en": "", "d": "高尔基复合体是由扁平膜囊、大囊泡和小囊泡以及管网结构等组成的极性细胞器，包含 顺面网状结构、顺面膜囊、中间膜囊、反面膜囊、反面网状结构。高尔基复合体和细胞的分 泌功能有关，对 ER 中转运来的脂类和蛋白分子进行分拣、加工、修饰以及分类和包装，且 参与糖蛋白和黏多糖的合成。"}, {"ch": "ch07", "t": "胞内体", "en": "", "d": "胞内体是膜包裹的囊泡结构，有初级胞内体和次级胞内体之分，初级胞内体通常位于细 胞质的外侧，次级胞内体常位于细胞质的内侧，靠近细胞核。胞内体膜上具有 ATPase-H ＋   质子泵，使其内部为酸性。初级胞内体是细胞胞吞作用形成的含有内含物的膜囊结构。在次 级胞内体酸性条件下，受体同结合的配体分裂，重新循环到细胞质膜表面或高尔基体反面网 络。"}, {"ch": "ch07", "t": "乙醛酸循环体", "en": "", "d": "乙醛酸循环体是指一种只存在于植物细胞中的过氧化物酶体。在种子萌发过程中，过氧 化物酶体降解储存在种子中的脂肪酸，产生乙酰辅酶 A，并进一步形成琥珀酸，后者离开过 氧化物酶体进一步转变成葡萄糖，上述转化过程中伴随一系列乙醛酸循环的反应，"}, {"ch": "ch08", "t": "蛋白质跨膜运输", "en": "transmembrane transport", "d": "蛋白质跨膜运输（transmembrane transport）主要指细胞质基质中合成的蛋白质转运到内 质网、线粒体和过氧化物酶体等部位的一种蛋白质运输类型。"}, {"ch": "ch08", "t": "膜泡运输", "en": "vesicular transport", "d": "膜泡运输（vesicular transport）是普遍存在于真核细胞中的，蛋白运输的一种特有方式。 蛋白质通过不同类型的转运小泡从其粗面内质网合成部位转运至高尔基体，进而分选运至细 胞的不同部位，在转运过程中不仅涉及蛋白本身的修饰、加工和组装，还涉及多种不同膜泡 定向运输极其复杂的调控过程。"}, {"ch": "ch08", "t": "选择性门控转运", "en": "selective gated transport", "d": "选择性门控转运（selective gated transport）是指在细胞质基质中合成的蛋白质通过核孔 复合体选择性的完成核输入或从细胞核返回细胞质。"}, {"ch": "ch08", "t": "Sar 蛋白", "en": "protein Sar", "d": "Sar 蛋白（protein Sar）是 COPⅡ包被蛋白中一种小的 GTP 接合蛋白，它作为分子开关 而起调节作用，主要是调节膜泡包被的装配与去装配。当 Sar 蛋白结合 GTP 后被激活并与 内质网膜结合，同时引发其他包被蛋白组分在 ER 膜上装配、出芽，随即形成 COPⅡ又被小 泡。"}, {"ch": "ch08", "t": "SNAREs", "en": "soluble NSF attachment protein recepter", "d": "SNAREs（soluble NSF attachment protein recepter）是指真核细胞生物膜上的跨膜蛋白大 家族，负责介导真核细胞内的膜泡运输。存在于囊泡膜上的称为 vSNARE，存在于靶膜上的 称为 tSNARE，SNAP 与 SNARE 相互作用，指导囊泡的定向运输。"}, {"ch": "ch08", "t": "内含信号序列", "en": "internal signal peptides", "d": "内含信号序列又称内含信号肽（internal signal peptides），是膜蛋白中特有的，它不位 于 N 端，但具信号序列的作用，故称为内含信号序列。它可作为蛋白质共翻译转移的信号 被 SRP 识别，同时它也是起始转移信号，可插入蛋白质转运通道，并与通道中的受体结合， 引导其后的肽序列转运。内含信号序列是不可切除的信号序列，而且是疏水性的。"}, {"ch": "ch08", "t": "停止转移肽", "en": "halt transfer signal", "d": "停止转移肽又称停止转运信号（halt transfer signal），它是存在于新生肽中能够使肽链 通过膜转移停止的一段信号序列，结果导致蛋白质锚定在膜的双脂层，停止转运信号以α螺 旋的形式锚定在双脂层。因停止转移信号的作用而形成单次跨膜的蛋白质，那么该蛋白在结 构上只有一个停止转移信号序列，没有内含转移信号，但在 N 端有一个信号序列作为转移 起始信号。"}, {"ch": "ch08", "t": "细胞分泌", "en": "cell secretion", "d": "细胞分泌（cell secretion）是指动物细胞和植物细胞将在粗面内质网上合成而又非内质 网组成部分的蛋白质和脂通过小泡运输的方式经过高尔基体的进一步加工和分选运送到细 胞内相应结构、细胞质膜及细胞外的过程。分泌的物质包括各种酶类、激素、神经递质、局 部介质、血清蛋白、抗体，以及细胞外基质成分，在植物包括细胞壁成分。分泌活动可以分 为两种：一种是分泌的物质主要是供细胞内使用；另一种是要通过与细胞质膜的融合进入细 胞质膜或运输到细胞外。"}, {"ch": "ch08", "t": "共翻译转移", "en": "", "d": "共翻译转移是指蛋白质合成在游离核糖体上起始后，由信号肽引导转移至糙面内质网， 然后新生肽边合成边转入糙面内质网中，在糙面内质网和高尔基体中经加工包装转移至指定 位置的肽链转移机制。"}, {"ch": "ch09", "t": "细胞通讯", "en": "cell communication", "d": "细胞通讯（cell communication）是指一个细胞发出的信号通过某种介质传递到另一细胞， 并使其产生相应的反应。细胞通讯在多细胞生物体的发生和组织的构建，协调细胞的功能， 控制细胞的生长和分裂中发挥了重要的作用。"}, {"ch": "ch09", "t": "信号转导", "en": "signal transduction", "d": "信号转导（signal transduction）是指外界信号（如光、电、化学分子）作用于细胞表面 受体，引起胞内信使的浓度变化，进而导致细胞应答反应的一系列过程。"}, {"ch": "ch09", "t": "G 蛋白", "en": "trimeric GTP-binding regulatory protein", "d": "G 蛋白（trimeric GTP-binding regulatory protein）是三聚体 GTP 结合蛋白，由α、β和γ 三个亚基组成，α亚基结合 GDP 处于关闭状态，结合 GTP 处于开启状态。α亚基具有 GTP 酶活性，能催化所结合的 ATP 水解，恢复无活性的三聚体状态。在细胞信号转导过程中起 着分子开关的作用。"}, {"ch": "ch09", "t": "受体酪氨酸磷酸酯酶", "en": "receptor tyrosin phosphatases", "d": "受体酪氨酸磷酸酯酶（receptor tyrosin phosphatases）是一次性跨膜蛋白受体，受体胞内 区具有蛋白酪氨酸磷酸酯酶活性，结合配体后，使磷酸化的酪氨酸去磷酸化，可逆转 RTK 的作用，在细胞周期调控中也发挥着重要作用。"}, {"ch": "ch09", "t": "双信使系统", "en": "double messenger system", "d": "双信使系统（double messenger system）是指磷脂酰肌醇信号通路的胞外信号被膜蛋白 受体接受后，同时产生两个胞内信使，分别启动两个信号传递途径即 IP3-Ca2+和 DG-PKC 途 径，实现细胞对外界信号的应答的一种信号系统。"}, {"ch": "ch09", "t": "离子通道耦联受体", "en": "", "d": "离子通道耦联受体是由多亚基组成的受体一离子通道复合体，本身既有结合位点，又是 离子通道，其跨膜信号转导无需中间步骤。"}, {"ch": "ch09", "t": "钙调蛋白", "en": "CaM", "d": "钙调蛋白（CaM）是一种真核细胞普遍存在的 Ca2 应答蛋白，含有 4 个结构域，每个 ＋   结构域可结合一个 Ca2 。CaM 本身无活性，它活化靶酶过程可分为两步：Ca2 与 CaM 结合 ＋                       ＋   形成活化态的 Ca2 -CaM 复合体；与靶酶结合将其活化。CaM 活化靶酶是一个受 Ca2 浓度 ＋                             ＋   控制的可逆反应。"}, {"ch": "ch09", "t": "分子开关", "en": "", "d": "分子开关是指通过激活机制或失活机制精确控制细胞内一系列信号传递级联反应的蛋白 质分子，可分为两类：一类分子开关蛋白的活性由磷酸化和去磷酸化控制，蛋白激酶使之磷 酸化而开放，蛋白磷酸酯酶使之去磷酸化而关闭，许多由可逆磷酸化控制的开关蛋白是蛋白 激酶本身；另一类分子开关蛋白是 GTP 结合蛋白，结合 GTP 而活化，结合 GDP 而失活。"}, {"ch": "ch09", "t": "第二信使", "en": "", "d": "第二信使是指受细胞外信号的作用，在细胞质溶质内形成或向细胞质溶质释放的细胞内 小分子，负责将信号传到细胞内部，如 cAMP、IP3、Ca2 等。第二信使通过其浓度变化（增 ＋   加或减少）应答胞外信号与细胞表面受体的结合，调节细胞内酶和非酶蛋白的活性，从而在 细胞信号转导途径中行使携带和放大信号的功能。"}, {"ch": "ch10", "t": "细胞骨架", "en": "cytoskeleton", "d": "细胞骨架（cytoskeleton）是指细胞中的蛋白纤维网架体系，包括微丝、微管和中间丝。 细胞骨架是一种高度动态的结构体系。其主要功能有结构与支持作用；胞内运输作用；收缩 与运动；空间组织。"}, {"ch": "ch10", "t": "基粒", "en": "basal body", "d": "基粒（basal body）是指位于鞭毛和纤毛根部，类似于动物细胞中的中心体，呈圆柱状 的微管性结构，平均大小为 0.2～0.5μm。其壁由 9 组微管三联体组成，包括完全微管与不 完全微管。胞质动力蛋白。中心粒和基粒是同源的，在某些时候可以相互转变，且都具有自 我复制能力。"}, {"ch": "ch10", "t": "肌球蛋白", "en": "myosin", "d": "肌球蛋白（myosin）是微丝的化学组成之一，有 1 杆部和 2 个头部，每个头部 2 条轻链， 具有 ATP 酶活性。头部具有肌动蛋白结合点，可与肌动蛋白结合，在粗肌丝中作为一种收 缩蛋白参与肌肉收缩活动。"}, {"ch": "ch10", "t": "肌原纤维", "en": "myofrbrils", "d": "肌原纤维（myofrbrils）是指肌纤维中许多纵行的，直径约 1μm 的圆筒状的微细结构， 与肌肉的收缩有直接关系。骨骼肌的肌原纤维的单位是肌节，藉 Z 线隔开，其中间有 A 带， 两侧有 I 带，明-暗重复单位是肌肉收缩和舒张最基本的功能单位。"}, {"ch": "ch10", "t": "微管组织中心", "en": "microtubule organizingcenter，MTOC", "d": "微管组织中心（microtubule organizingcenter，MTOC）是指微管在生理状态或实验处理 解聚后重新装配的发生处。如鞭毛基体、动物细胞中的中心体。微管组织中心决定了细胞微 管的极性，微管的负极指向微管组织中心，正极背向微管组织中心。"}, {"ch": "ch10", "t": "细胞松弛素", "en": "", "d": "细胞松弛素是真菌的一类代谢产物，与微丝结合后可以将微丝切断，并结合在微丝末端 阻抑肌动蛋白在该部位的聚合，是微丝聚合的特异性抑制剂，常用的有细胞松弛素 B 和细 胞松弛素 D。"}, {"ch": "ch10", "t": "微管相关蛋白", "en": "MAP", "d": "微管相关蛋白（MAP）即微管结合蛋白，是指一些与微管密切联系，附着于微管多聚 体上，参与微管装配并能增加微管稳定性的蛋白，包括 MAP1，MAP2，MAP3，tau 蛋白等。 微管相关蛋白多分布于神经元的树突和轴突中，一般认为与骨架纤维间的连接有关，可能决 定了轴突和树突的不同形态。"}, {"ch": "ch10", "t": "驱动蛋白与动力蛋白", "en": "", "d": "kinesin 的中文名称是驱动蛋白，cytoplasmatic dynein 的中文名称是细胞质动力蛋白。二 者均属于微管马达蛋白，主要负责为物质沿着微管运输提供能量。 二者的区别在于沿微管运动的方向不同。驱动蛋白从微管的（－）端移向微管的（＋）端， 是正端走向的微管发动机；细胞质动力蛋白是负端走向的微管发动机，担负小泡和各种膜结 合细胞器的运输任务，同时还是细胞分裂中染色体运动的动力来源。"}, {"ch": "ch11", "t": "亲核蛋白", "en": "karyophilic protein", "d": "亲核蛋白（karyophilic protein）是指在细胞质基质中合成后，需要或能够进入细胞核内 发挥功能的一类蛋白质。"}, {"ch": "ch11", "t": "骨架-放射环结构模型", "en": "scaffold radical loop structure model", "d": "骨架-放射环结构模型（scaffold radical loop structure model）是一种关于染色质包装的结 构模型。该模型认为，由非组蛋白等构成染色体骨架，30nm 的螺线管折叠成环，沿染色体 纵轴锚定在染色体骨架上，由中央向四周伸出，构成放射环。"}, {"ch": "ch11", "t": "异染色质", "en": "heterochromatin", "d": "异染色质（heterochromatin）指间期核内，染色质纤维压缩程度高，处于聚缩状态的染 色质组分，碱性染色体染色较深的那些染色质。"}, {"ch": "ch11", "t": "染色体", "en": "chromosome", "d": "染色体（chromosome）是在真核细胞有丝分裂期，染色质进一步紧密包装而成的遗传 物质的形态单位。"}, {"ch": "ch11", "t": "核仁组织区", "en": "nucleolar organizing region，NOR", "d": "核仁组织区（nucleolar organizing region，NOR）是指位于次缢痕区，rRNA 基因所在的 部位（5S rRNA 基因除外），与间期细胞核仁形成有关。"}, {"ch": "ch11", "t": "人工染色体", "en": "artificial chromosome", "d": "人工染色体（artificial chromosome）是指采用分子克隆技术，将真核细胞染色体的复制 起点、着丝粒和端粒这 3 种 DNA 关键序列分别克隆出来，再将它们互相搭配连接构成的染 色体。这种人工染色体可用作载体，克隆大片段的 DNA 分子。"}, {"ch": "ch11", "t": "核型", "en": "karyotype", "d": "核型（karyotype）是指染色体组在有丝分裂中期的表型，包括染色体数目、大小、形态 特征的总和，它具有种属特异性。进行核型分析对于探讨人类遗传疾病的机制、物种亲缘关 系与进化、远缘杂种的鉴定有重要的意义。"}, {"ch": "ch11", "t": "DNase I 超敏感位点", "en": "DNase I hypersensitive site，DHS", "d": "DNase I 超敏感位点（DNase I hypersensitive site，DHS）是指如用低浓度的 DNaseⅠ处 理染色质，具有转录活性或潜在转录活性的染色质被 DNaseⅠ降解成酸溶性的 DNA 小片段 后，能够首先被切割的少数特异位点。通常，DNase Ⅰ超敏感位点是染色质上无核小体的 DNA 片段，是活性染色质的基本特征之一，超敏感位点的建立是基因起始转录的必要而非 充分条件。"}, {"ch": "ch11", "t": "基因座控制区", "en": "locus control region，LCR", "d": "基因座控制区（locus control region，LCR）是指由许多增强子或隔离子等顺式作用元件 组成的 DNA 序列，它具有稳定染色质疏松结构的功能，可以控制基因座的各个基因顺序表"}, {"ch": "ch11", "t": "核体", "en": "nuclear bodies，NBs", "d": "核体（nuclear bodies，NBs）是指高等真核细胞的间期核内除染色质与核仁结构外，在 染色质之间的空间所含的许多形态上不同的亚核结构域。如螺旋体和早幼粒细胞白血病蛋白 体。"}, {"ch": "ch11", "t": "随体", "en": "", "d": "随体是指位于染色体末端的球形染色体节段，通过次缢痕区与染色体主体部分相连，位 于染色体末端的随体为端随体，位于两个次缢痕中间的为中间随体。随体主要由异染色质组 成，含高度重复的 DNA 序列，不具有常染色质的功能活性。"}, {"ch": "ch11", "t": "致密纤维组分", "en": "", "d": "致密纤维组分是核仁超微结构中密度最高的部分，呈环形或者半月形包围纤维中心，由 致密的纤维构成，通常见不到颗粒，rRNA 以很高的密度出现在 DFC。DFC 有特异性结合 蛋白，其中比较清楚的是核仁纤维蛋白、核仁蛋白和 Ag-NOR 蛋白。"}, {"ch": "ch11", "t": "端粒", "en": "", "d": "端粒是指染色体两端的特化结构，通常由富含鸟嘌呤核苷酸的短的串联重复序列 DNA 组成，伸展到染色体的 3＇端。端粒的长度与细胞及生物个体的寿命有关。端粒的生物学作 用在于维持染色体的完整性和独立性，可能还与染色体在核内的空间排布等有关。一个基因 组内的所有端粒都是由相同的重复序列组成，但不同物种的端粒的重复序列是不同的。"}, {"ch": "ch12", "t": "核糖体", "en": "ribosome", "d": "核糖体（ribosome）是几乎存在一切原核与真核细胞内（除极少数高度分化的细胞外）， 由蛋白质和 RNA 组成的没有被膜包裹，呈颗粒状的细胞结构。其唯一功能是按照 mRNA 的 指令由氨基酸高效且精确地合成多肽链。"}, {"ch": "ch12", "t": "多聚核糖体", "en": "polyribosome", "d": "多聚核糖体（polyribosome）是指具有特殊功能与形态结构的核糖体与 mRNA 的聚合体。 核糖体在细胞内并不是单个独立地执行功能，而是由多个甚至几十个核糖体串连在一条 mRNA 分子上高效地进行肽链的合成。"}, {"ch": "ch12", "t": "剪接子", "en": "", "d": "剪接子是由 RNA 和蛋白质分子构成的，具有切去 RNA 的内含子并把外显子连接起来 的功能的复合体。"}, {"ch": "ch12", "t": "氯霉素", "en": "", "d": "氯霉素是由链霉菌属产生的一种抗生素，可与 70S 的核糖体结合抑制蛋白质的合成。 抑制方式是，抑制肽基转移酶（T 因子）活性，使其不能形成肽键。"}, {"ch": "ch12", "t": "ribosome", "en": "", "d": "（1）核糖体 核糖体是一种核糖核蛋白颗粒，由 60%的 rRNA 与 40%的 r 蛋白质构成，是细胞内合成蛋白 质、没有膜包被的细胞器，其功能是按照 mRNA 的信息将氨基酸高效精确地合成蛋白质多 肽链。核糖体按沉降系数分为两类，一类（70S）存在于细菌等原核生物中，另一类（80S） 存在于真核细胞的细胞质中。 （2）核小体 核小体是由 DNA 缠绕组蛋白构成的一级染色质结构，是染色体的基本组成单位。每个核小 体包括 200bp 左右的 DNA 和一个组蛋白八聚体（两分子的 H2A•H2B 和两分子的 H3•H4） 以及一分子的组蛋白 H1，其中 H1 稳定核小体，两个相邻核小体之间以连接 DNA 相连。"}, {"ch": "ch13", "t": "有丝分裂", "en": "mitosis", "d": "有丝分裂（mitosis）是真核细胞分化与增殖的基本方式，分为核分裂和胞质分裂，DNA 及其他物质如蛋白等复制了的细胞平均分配到两个子细胞的过程。真核生物细胞在形成染色 体和纺锤体等丝状结构的同时发生复杂的核内变化。"}, {"ch": "ch13", "t": "动粒", "en": "kinetochore", "d": "动粒（kinetochore）是指在主缢痕处 2 个染色单体的外侧表层部位的特殊结构，它与染 色体微管接触，是微管蛋白的组织中心，又称着丝点。"}, {"ch": "ch13", "t": "纺锤体", "en": "spindle", "d": "纺锤体（spindle）是指减数和有丝分裂中期，细胞质中出现的纺锤形结构，由能收缩的 微管和微丝纵向成束排列而成。"}, {"ch": "ch13", "t": "姐妹染色单体", "en": "sister chromatid", "d": "姐妹染色单体（sister chromatid）是指染色体分裂间期进行自我复制，所形成的由一个 着丝点连接着的两条完全相同的染色单体。"}, {"ch": "ch13", "t": "分裂中期阻断法", "en": "metaphase blocking", "d": "分裂中期阻断法（metaphase blocking）是指应用可以抑制微管聚合的某些药物，如秋水 仙素、秋水酰胺和 noeodazole 等，从而有效抑制细胞分裂器的形成，将细胞阻断在分裂中期 的细胞周期同步方法。"}, {"ch": "ch13", "t": "中间体", "en": "midbody", "d": "中间体（midbody）是指在分裂沟下方，除肌动蛋白之外，还有微管、小膜泡等物质聚 集，共同构成的一个环形致密层。"}, {"ch": "ch13", "t": "细胞分裂", "en": "", "d": "细胞分裂是指一个细胞（母细胞）分裂成两个以上细胞（子细胞）的现象。由于细胞分 裂，核及细胞器分配给两个子细胞。细胞分裂分为有丝分裂和减数分裂两种主要的分裂方式"}, {"ch": "ch13", "t": "胞质分裂", "en": "", "d": "胞质分裂是指在细胞分裂末期时，通常于核分裂之后接着发生的胞质体的分裂。根据生 物种类的不同，胞质分裂可分为两个基本类型：一是在高等植物细胞中，于细胞分裂的后期， 姐妹染色单体群移到两极之后，纺锤体的中间区域分化为膜体。在末期，从纺锤体中部形成 细胞板；二是在动物细胞中，于细胞分裂的末期，赤道板位置上的表层细胞质部位向中间凹 陷缢缩。另外，在一部分植物细胞中，以及在酵母出芽和粘菌的孢子形成时等，可以看到有 介于这两种类型之间的中间型。"}, {"ch": "ch13", "t": "细线期", "en": "", "d": "细线期是指第一次减数分裂前期的最初时期。在这个时期，染色质凝集成单条细线，细 线与核膜相连，染色质线上有染色粒。"}, {"ch": "ch13", "t": "双线期", "en": "", "d": "双线期是指在第一减数分裂前期，继粗线期的时期。在这一时期，重组阶段结束，同源 染色体相互分离，仅留几处相互联系，四分体结构变得清晰可见。在双线期可见染色体交叉。"}, {"ch": "ch13", "t": "着丝点", "en": "", "d": "着丝点是在主缢痕处 2 个染色单体的外侧表层部位的特殊结构，它与染色体微管相接触， 是微管蛋白的组织中心，着丝点又称动粒或动原粒"}, {"ch": "ch13", "t": "核内有丝分裂", "en": "", "d": "核内有丝分裂是指在核分裂过程中核膜始终保持完整的一种有丝分裂方式。纺锤丝可以 完全局限在核内，如酵母菌；也可伸出核膜以外，但仍保持核膜的完整性。"}, {"ch": "ch13", "t": "联会复合体", "en": "", "d": "联会复合体是指同源染色体之间在减数分裂前期联会时所形成的一种临时性结构，是一 种减数分裂特异性超分子蛋白质结构，与减数分裂 I 中同源染色体的凝缩、配对、重组和分 离密切相关。联会复合体从细线期开始组装，经过偶线期至粗线期形成典型的联会复合体结 构，同时在粗线期重组节开始组装。双线期联会复合体开始去装配，终变期时完全消失。"}, {"ch": "ch13", "t": "减数分裂", "en": "", "d": "减数分裂是指细胞仅进行一次 DNA 复制，随后进行两次分裂，染色体数目减半的一种 特殊的有丝分裂。减数分裂是仅发生于有性生殖细胞形成过程中的某个阶段的一种特殊的有 丝分裂形式，整个过程分为减数分裂Ⅰ和减数分裂Ⅱ两个阶段。"}, {"ch": "ch13", "t": "诱导同步", "en": "", "d": "诱导同步是指用物理、化学方法处理培养细胞，使所有细胞群停留在细胞周期的某一时 相，从而使它们的分裂周期同步化的方法。目前应用较广泛的诱导同步方法主要有两种，即 DNA 合成阻断法和分裂中期阻断法。"}, {"ch": "ch13", "t": "细胞周期同步化", "en": "", "d": "细胞周期同步化是指在自然过程中发生的或经人为处理造成的所有细胞处于同一细胞周 期阶段的过程。前者称为天然同步化，后者称为人工同步化。人工同步化包括人工选择同步 化和人工诱导同步化（DNA 合成阻断法和分裂中期阻断法）。"}, {"ch": "ch13", "t": "有丝分裂器", "en": "", "d": "有丝分裂器是一个动态的结构，在中期细胞中包括两部分：①纺锤体，是由对称的微管 束组成的形似橄榄球的结构，在细胞的赤道板被染色体一分为二；②星体，在纺锤体的两端 各有一个，为一簇呈放射状的微管。"}, {"ch": "ch13", "t": "细胞周期", "en": "", "d": "细胞周期是指从第一次细胞有丝分裂结束到第二次分裂完成所经历的过程，包括分裂间 期和分裂期（M 期）。其中分裂间期是指第一次分裂结束到第二次分裂开始的时间，是细 胞增殖的物质准备和积累阶段，包括 G1 期、S 期（DNA 合成）和 G2 期。M 期是指一次分 裂开始到结束的时间，包括前期、中期、后期和末期。"}, {"ch": "ch14", "t": "检验点", "en": "checkpoint", "d": "检验点（checkpoint），又称限制点，指细胞对一些环境因素有一敏感点，可以限制细 胞通过周期，是控制 cell 增殖的关键。"}, {"ch": "ch14", "t": "成熟促进因子", "en": "MPF", "d": "成熟促进因子（MPF）是指由 CDK1 和周期蛋白 B 结合而成，调控细胞由 G2 期向 M 期转化的一种酶。"}, {"ch": "ch14", "t": "染色体超前凝集", "en": "PCC", "d": "染色体超前凝集（PCC）是指与 M 期细胞融合的间期细胞发生的形态各异的染色体凝 集。"}, {"ch": "ch14", "t": "细胞周期依赖激酶", "en": "CDK", "d": "细胞周期依赖激酶（CDK），即周期蛋白依赖性蛋白激酶，是一类含有一段类似氨基 酸序列的蛋白，它们可以和周期蛋白结合并受后者的调，可以磷酸化其他蛋白，比如组蛋白 H1、核纤层蛋白等，在细胞周期调控中发挥重要的作用。"}, {"ch": "ch14", "t": "细胞周期蛋白", "en": "cyclins", "d": "细胞周期蛋白（cyclins）是结合并调节 CDK 的活性的一类蛋白，其含量随细胞周期进 程变化而变化，一般在细胞间期内积累，在细胞分裂期消失，在下一个细胞周期中又重复出 现，其含有一段比较保守的氨基酸序列。"}, {"ch": "ch14", "t": "泛素-蛋白酶体途径", "en": "", "d": "泛素-蛋白酶体途径是细胞内降解短寿命蛋白质的重要途径，与细胞多种生理功能调节 密切相关。首先通过酶 El、E2 和 E3 的作用使将要被降解的蛋白质泛素化，再由蛋白酶体 使泛素化的蛋白质完全水解。"}, {"ch": "ch14", "t": "肿瘤坏死因子", "en": "", "d": "肿瘤坏死因子是主要的死亡配体，最初发现存在于注射细菌脂多糖后的小鼠血清中，能 够使肿瘤组织出血坏死。肿瘤坏死因子主要由激活的单核-巨噬细胞分泌，诱导细胞凋亡和 诱发炎症反应是其主要的生理效应。肿瘤坏死因子的生物学功能是通过与细胞表面的受体结 合来实现的。"}, {"ch": "ch14", "t": "oncogene", "en": "", "d": "（1）癌基因 癌基因是控制细胞生长和分裂的正常基因，其突变能引起正常细胞癌变。癌基因可分为病毒 癌基因和细胞癌基因两大类。病毒癌基因是指反转录病毒的基因组里带有可使受病毒感染的 宿主细胞发生癌变的基因。细胞癌基因即原癌基因，是指在正常细胞基因组中对细胞正常生 命活动起主要调控作用的基因，在发生突变或被异常激活后变成具有致癌能力的癌基因。 （2）肿瘤抑制因子 肿瘤抑制因子又称抑癌基因，是正常细胞增殖过程中的负调控因子，它编码的蛋白在细胞周 期的检验点上起阻遏周期进程的作用。抑癌基因有两个拷贝，其中一个拷贝正常，可保证正 常的调控作用，两个拷贝都丢失或失活，才能引起细胞增殖的失控。 抑癌基因与癌基因之间的区别：癌基因的突变性质为显性，抑癌基因的突变性质为隐性。"}, {"ch": "ch14", "t": "早熟染色体凝集", "en": "PCC", "d": "早熟染色体凝集（PCC）是指 M 期细胞与其他间期细胞在一定介质（如仙台病毒）介 导下发生融合，继续培养一段时间后，与 M 期细胞融合的间期细胞发生了形态各异的染色 体凝集现象。G1 期 PCC 为细单线状，S 期 PCC 为粉末状，G2 期 PCC 为双线染色体状。"}, {"ch": "ch15", "t": "细胞分化", "en": "cell differentiation", "d": "细胞分化（cell differentiation）是指在在个体发育中，由一种相同的细胞类型经细胞分 裂后逐渐在形态、结构和功能上形成稳定性差异，产生各不相同的细胞类群的过程。"}, {"ch": "ch15", "t": "组合调控", "en": "combinational control", "d": "组合调控（combinational control）是有限的少量调控蛋白启动为数众多的特异细胞类型 的分化的调控机制。即每种类型的细胞分化是由多种调控蛋白共同调节完成的。"}, {"ch": "ch15", "t": "再生", "en": "regeneration", "d": "再生（regeneration）一般是指生物体缺失部分后重建过程，广义的再生可包括分子水平、 细胞水平、组织与器官水平及整体水平的再生。"}, {"ch": "ch15", "t": "单能干细胞", "en": "monopotential cell", "d": "单能干细胞（monopotential cell），又称定向干细胞（directional stem cell）指仅具有分 化形成某一种类型能力的细胞"}, {"ch": "ch15", "t": "细胞决定", "en": "cell determination", "d": "细胞决定（cell determination）是指在能识别一个细胞的分化以前，就有了一个预先保 证细胞怎样变化的时期，或者说在形态、结构与功能等分化特征尚未显现之前就已经确定了 细胞的命运。"}, {"ch": "ch15", "t": "转化细胞", "en": "transformed cell", "d": "转化细胞（transformed cell）是指体外生长的正常细胞受肿瘤病毒感染后，在形态和生 理代谢方面都产生了新的特性，且可不受控制地繁殖下去的细胞，若这种经转化的细胞具有 癌细胞属性则称为恶性转化细胞。"}, {"ch": "ch15", "t": "增强子", "en": "enhancer", "d": "增强子（enhancer）是指在真核生物基因的上游或下游存在的能增强基因转录的特异 DNA 顺序。"}, {"ch": "ch15", "t": "剪接增强子", "en": "splicing enhancer", "d": "剪接增强子（splicing enhancer）是指位于那些保留与否受到调节的外显子内的特殊 RNA 序列，其功能是结合特殊的蛋白质，决定弱剪接位点的识别和使用。"}, {"ch": "ch15", "t": "顶体反应", "en": "", "d": "顶体反应是受精作用的反应之一，受钙离子的调节。反应过程较长，包括顶体受体的激 活、顶体膜与精细胞质膜融合、顶体中水解酶的释放、卵细胞外被（透明带）的水解等，最 终导致精细胞质膜与卵细胞质膜的融合。"}, {"ch": "ch15", "t": "同源异型基因", "en": "", "d": "同源异型基因是指存在于多种无脊椎动物和高等脊椎动物中的一类在体节发育中起关键 作用的基因，在基因表达调控中具有主导性作用。这些基因都含有一个称为同源框的 180bp 长的 DNA 序列，编码的同源异型结构域形成的α螺旋-转角-α螺旋结构作为反式作用因子启 动特定基因的表达。"}, {"ch": "ch15", "t": "反式作用因子", "en": "", "d": "反式作用因子是指对核酸链上的基因表达起到调控作用的蛋白，编码该蛋白的基因与其 识别结合作用的核酸链不是同一链。"}, {"ch": "ch15", "t": "管家基因", "en": "", "d": "管家基因是指所有细胞中均表达的一类基因，其产物是维持细胞基本生命活动所必需的。 如微管蛋白基因、糖酵解酶系基因与核糖体蛋白基因等。一般管家基因转录的起始部位没有 TATA 框，仅有 CG 富集区(又称 CG 岛)，其内含子相对很短。管家基因编码的产物多为细 胞基础代谢活动所需的酶类、核糖体蛋白、膜转运蛋白，以及细胞周期调控的主要蛋白质等 细胞生命活动必需的蛋白质。"}, {"ch": "ch15", "t": "细胞全能性", "en": "", "d": "细胞全能性是指细胞经分裂和分化后仍具有形成完整有机体的潜能或特性。动物的受精 卵及卵裂早期的胚胎细胞是具有全能性的细胞。植物的体细胞在适宜的条件下可培育成正常 的植株，为细胞全能性提供了有力的证据，而且也广泛地应用在植物基因工程的实践中。"}, {"ch": "ch15", "t": "去分化", "en": "", "d": "脱分化又称去分化，是指分化细胞失去其特有的结构与功能变成具有未分化细胞特征的 过程。植物的体细胞在一定条件下形成未分化的细胞团——愈伤组织，即为脱分化现象，愈 伤组织可进一步被诱导，使其再分化形成根和芽的顶端分生组织的细胞，并最终长成植株。 高等动物的克隆也涉及细胞去分化的过程，但已分化细胞的细胞核需要在卵细胞质中才能完 成其去分化的程序。"}, {"ch": "ch16", "t": "细胞凋亡", "en": "apoptosis", "d": "细胞凋亡（apoptosis）是一种有序的或程序性的细胞死亡方式，是细胞接受某些特定信 号刺激后进行的正常生理应答反应。该过程具有典型的形态学和生化特征，凋亡细胞最后以 凋亡小体被吞噬消化。"}, {"ch": "ch16", "t": "凋亡复合体", "en": "apotosome", "d": "凋亡复合体（apotosome）是指凋亡分子 Apaf-1 与细胞色素 c 形成的复合体，相对分子 量为（700～1400）×103，细胞质中 Caspase-9 的前体被募集到复合体上并发生自动切割活化， 引起细胞凋亡。"}, {"ch": "ch16", "t": "细胞坏死", "en": "necrosis", "d": "细胞坏死（necrosis）是细胞“程序性死亡”的另一种形式，具有包括引发炎症反应在内 的重要生理功能。当细胞凋亡不能正常发生而细胞必须死亡时，坏死作为凋亡的“替补”方式 被细胞采用；此外，分裂旺盛细胞的 DNA 被持续损伤，也能引发细胞坏死，推测原因可能 是 RARP 被活化。"}, {"ch": "ch16", "t": "成纤维细胞", "en": "", "d": "成纤维细胞是构成纤维性结缔组织的重要成分。细胞特点是：外形长而扁平，常有不规 则的突起；细胞质内含有线粒体、高尔基体、中心体、微脂肪粒等、其他无特殊的分化；细 胞核呈椭圆形，有明显的核仁，细胞核染色性差。成纤维细胞常与胶原纤维紧密相连，因与 胶原纤维的形成有关故称为成纤维细胞。"}, {"ch": "ch16", "t": "阻遏", "en": "", "d": "阻遏是指基因的表达在信使 RNA 合成（转录）阶段为特异的调节因子（阻遏物）所抑 制，使细胞内特定的酶或酶系合成率降低的现象。当特定的代谢物质在细胞内的浓度增加时， 阻遏物就被活化，而相应结构基因群（操纵子）的特异物质的产生就受到抑制。"}, {"ch": "ch16", "t": "胞质体", "en": "", "d": "胞质体是指除去细胞核后由膜包裹的无核细胞。"}, {"ch": "ch16", "t": "程序性细胞死亡", "en": "", "d": "程序性细胞死亡是细胞的一种生理性、主动性的“自杀”现象，是主动由基因决定的细胞 自动结束生命的过程。这些细胞死得有规律，似乎是按编好了的“程序”进行的，是生物体在 漫长进化过程中逐步建立的细胞“自杀”机制，其重要作用是清除多余的、受损的、癌变的或 微生物感染的细胞，维持机体内环境的稳定。程序性细胞死亡的类型有多种，细胞凋亡只是 其中之一。"}, {"ch": "ch16", "t": "自由基", "en": "", "d": "自由基是具有高度活性、通常寿命短暂的分子片段具有的一个或多个未配对电子。自由 基的种类很多，活性最强的是氧中心自由基，简称氧自由基，包括 O2（超氧自由基）、·OH （羟自由基）和 H2O2。"}, {"ch": "ch16", "t": "细胞凋亡即程序性细胞死亡", "en": "PCD", "d": "细胞凋亡即程序性细胞死亡（PCD），是指细胞在一定的生理或病理条件下，受内在遗 传机制的控制自动结束生命的过程。细胞凋亡是多细胞有机体为调控机体发育，维护内环境 稳定，由基因控制的细胞主动死亡过程。主要形态特征包括细胞核浓缩、染色体 DNA 被以 核小体为单位切成梯状片段、细胞凋亡小体形成等。"}, {"ch": "ch16", "t": "细胞自噬", "en": "", "d": "细胞自噬是指细胞通过溶酶体与双层膜包裹的细胞自身物质融合，从而降解细胞自身物 质的过程。。正常的动物细胞为了维持细胞内环境的动态平衡，需要不断降解功能失常或不 需要的细胞结构，如各种蛋白质、细胞器以及各种胞质组分。通常，寿命较短的蛋白质如调 控蛋白等通过泛素-蛋白酶体系统进行降解；而寿命较长的细胞结构及蛋白质通过细胞自噬 途径，由溶酶体进行降解。细胞自噬的特征是细胞中出现大的双层膜包裹的自噬泡即自噬小 体。"}, {"ch": "ch17", "t": "细胞连接", "en": "cell junction", "d": "细胞连接（cell junction）是指在细胞质膜的特化区域，通过膜蛋白、细胞支架蛋白或者 胞外基质形成的细胞与细胞之间、细胞与胞外基质间的连接结构。细胞连接是多细胞生物体 相邻细胞之间协同作用的重要方式。"}, {"ch": "ch17", "t": "胞间连丝", "en": "plasmodesmata", "d": "胞间连丝（plasmodesmata）是指在高等植物细胞中，由相互连接的相邻细胞的细胞膜 共同组成管状结构，中央有内质网形成的连丝微管。它是植物细胞通讯连接的主要方式，其 功能是进行选择性的物质转运和细胞通讯。"}, {"ch": "ch17", "t": "选择素", "en": "selectin", "d": "选择素（selectin）是一类属异亲型、依赖 Ca2+的，胞外部分具有高度保守的凝集素（1ectin） 结构域，特异性识别其他细胞表面寡糖链末端糖基配体。主要参与白细胞与脉管内皮细胞之 间的识别与黏着。已发现 P（Platelet）选择素、E（Endothelial）选择素和 L（Leukocyte） 选择素等。"}, {"ch": "ch17", "t": "锚定依赖性生长", "en": "anchorage-dependentgrowth", "d": "锚定依赖性生长（anchorage-dependentgrowth）是指大多数正常细胞必须附着在胞外基 质上才能成功生长，即使培养基中含有刺激细胞增殖的生长因子，如果细胞不能贴附在胞外 基质上也会停止分裂直至凋亡的现象。"}, {"ch": "ch17", "t": "胶原", "en": "collagen", "d": "胶原（collagen）是胞外基质最基本结构成分之一，是动物体内含量最丰富的蛋白。原 胶原是胶原纤维的基本结构单位；原胶原是由三条肽链盘绕成的三股螺旋结构，一级结构具 有 Gly-x-y 重复序列；在胶原纤维内部，原胶原蛋白分子呈 1/4 交替平行排列，使胶原形成 周期性横纹。生物学功能：胶原赋予组织刚性及抗张力作用；使组织具有牢固、不易变 形的特点；可被胶原酶特异降解，而参入胞外基质信号传递的调控网络中。"}, {"ch": "ch17", "t": "通讯连接", "en": "", "d": "通讯连接是指以细胞之间建立的连接通道为基础的细胞连接方式，这种通道既使细胞之 间彼此结合，又介导细胞之间的通讯联系，即依靠某些亲水分子或离子在通道间的流动沟通 信息。例如，广泛存在于人体及动物各种组织间的间隙连接、神经细胞间的化学突触和植物 细胞中的胞间连丝等都属于通讯连接。"}, {"ch": "ch17", "t": "黏着斑", "en": "", "d": "黏着斑是细胞与胞外基质之间的连接方式，参与的细胞骨架结构组分是微丝、跨膜粘连 蛋白是整联蛋白，有利于细胞在运动过程中的张力以及细胞生长的信号传递。"}, {"ch": "ch17", "t": "透明质酸", "en": "", "d": "透明质酸是一种重要的糖胺聚糖，是增殖细胞和迁移细胞胞外基质的主要成分，尤其在 早期胚胎中含量特别丰富。"}, {"ch": "ch17", "t": "细胞外基质", "en": "", "d": "细胞外基质是指分布于细胞外空间，由细胞分泌的蛋白和多糖所构成的网络结构。其为 细胞的生存及活动提供适宜的场所，并通过信号转导系统影响细胞的形状、代谢、功能、迁 移、增殖和分化。细胞外基质成分有：①结构蛋白，包括胶原和弹性蛋白，分别赋予胞外基 质强度和韧性；②蛋白聚糖，由蛋白质和多糖共价形成，具有高度亲水性，赋予胞外基质抗 压的能力；③粘连糖蛋白，包括纤连蛋白和层粘连蛋白，有助于细胞粘连到胞外基质上。"}, {"ch": "ch17", "t": "连接子", "en": "", "d": "连接子是构成间隙连接的基本单位。每个连接子由 6 个相同或相似的跨膜蛋白亚单位环 绕，中心形成一个直径为 1.5nm 的亲水性通道。相邻细胞质膜上的两个连接子对接形成完整 的间隙连接结构。"}, {"ch": "ch17", "t": "desmosome", "en": "", "d": "桥粒和半桥粒都是与中间丝相连的锚定连接。 （1）桥粒是细胞与细胞之间的锚定连接，锚蛋白一侧与细胞内的中间丝相连，另一侧与跨 膜的黏附性蛋白质相连。通过桥粒连接，使整个上皮层的中间丝形成一个完整的网络，增强 了细胞抵抗外界压力与张力的机械强度。 （2）半桥粒是细胞与细胞外基质之间的连接。锚蛋白与一侧与细胞内的中间丝相连，另一 侧与跨膜的整联蛋白相连，整联蛋白与胞外基质的层粘连蛋白相连，从而将细胞锚定在细胞 外基质上。"}, {"ch": "ch17", "t": "整合素", "en": "", "d": "整合素即整联蛋白，是一种由α和β两个亚基形成异源二聚体的细胞黏着因子，整合素可 与不同的配体结合，从而介导细胞与基质、细胞与细胞之间的黏着，其识别的主要部位是配 体上的 RGD 三肽结构，整合素还在细胞内外信号转导中起着十分重要的作用。"}, {"ch": "通用", "t": "细胞", "en": "cell", "d": "是组成包括人类在内的所有生物体的基本单位，这一基本单位的含义即包括结构上的，也包括功能上的。"}, {"ch": "通用", "t": "医学细胞生物学", "en": "medical cell biology", "d": "以人体或医学为对象的细胞生物学研究或学科。"}, {"ch": "通用", "t": "生物大分子", "en": "biological macromolecules", "d": "也称多聚体，由许多小分子单体通过共价键连接而成，相对分子质量比较大，包括蛋白质、核酸和多糖等。"}, {"ch": "通用", "t": "多肽链", "en": "polypeptide chain", "d": "多个氨基酸通过肽键组成的肽称为多肽链。"}, {"ch": "通用", "t": "细胞蛋白质组", "en": "proteome", "d": "将细胞内基因活动和表达后所产生的全部蛋白质作为一个整体，研究在个体发育的不同阶段，在正常或异常情况下，某种细胞内所有蛋白质的种类、数量、结构和功能状态，从而阐明基因的功能。"}, {"ch": "通用", "t": "细胞膜", "en": "cell membrane", "d": "又称质膜，是指围绕在细胞最外层，由脂质、蛋白质和糖类所组成的生物膜。"}, {"ch": "通用", "t": "生物膜", "en": "biological membrane", "d": "人们把生物膜和细胞内各种模性结构统称为生物膜。"}, {"ch": "通用", "t": "单位膜", "en": "unit membrane", "d": "生物膜在电镜下呈现出较为一致的3层结构，即电子致密度高的内、外两层之间夹着电子密度较低的中间层。"}, {"ch": "通用", "t": "细胞外被", "en": "cell coat", "d": "细胞外被即为细胞膜中糖蛋白和糖脂伸出细胞外表面分支或不分支的寡糖链，其蛋白质和脂质部分参加了细胞膜本身的构造。"}, {"ch": "通用", "t": "细胞表面", "en": "cell surface", "d": "细胞膜、细胞外被、细胞内面的胞质溶胶、各种细胞连接结构和细胞膜的一些特化结构统称为细胞表面。"}, {"ch": "通用", "t": "残质体", "en": "residue body", "d": "吞噬溶酶体到达终末阶段，水解酶活性下降，还残留一些未被消化和分解的物质，形成在电镜下电子密度高、色调较深的残余物，这时的溶酶体称为残质体。"}, {"ch": "通用", "t": "类核体", "en": "nucleoid", "d": "有的过氧化物酶体中央含有电子密度高、呈规则形的结晶状结构，称类核体，实质是尿酸氧化酶的结晶。"}, {"ch": "通用", "t": "线粒体", "en": "mitochondrion", "d": "是细胞进行生物氧化和能量转换的主要场所，被称为能量转换器，细胞生命活动所需能量的80﹪由线粒体提供，所以线粒体被比喻为细胞的“动力工厂”。"}, {"ch": "通用", "t": "嵴内空间", "en": "intracristal space", "d": "线粒体由于嵴向内腔突进造成的外腔向内伸入的部分称为嵴内空间。"}, {"ch": "通用", "t": "嵴间腔", "en": "intercristal space", "d": "线粒体嵴与嵴之间部分称为嵴空间。"}, {"ch": "通用", "t": "基质导入序列", "en": "matrix-targeting sequence,WTS", "d": "又称导肽，是输入线粒体的蛋白质在其 N 端具有的一段氨基酸序列，能够被线粒体膜上的受体识别并结合，从而定向蛋白质的转运。"}, {"ch": "通用", "t": "动态微管", "en": "dynamic microtuble", "d": "细胞中有的微管存在时间很短，发生快速组装和去组装，称动态微管，如纺锤体。"}, {"ch": "通用", "t": "染色质", "en": "chromatin", "d": "是细胞核内能被碱性染料着色的物质，也是遗传性息的载体。"}, {"ch": "通用", "t": "核小体", "en": "nucleosome", "d": "是构成染色质的基本单位结构。每个核小体由5种组蛋白和200bp 左右的 DNA 组成，其中 H2A、H2B、H3、H4各两分子形成八聚体，构成核心颗粒。DNA 分子以左手螺旋缠绕在核心颗粒表面，每圈约80bp，共1.75圈，约146bp，相邻核心颗粒之间为一段60bp 的连接 DNA，H1位于 DNA 进出核心颗粒的结合处，功能与染色质的浓缩有关，形成直径为11nm 的核小体。"}, {"ch": "通用", "t": "常染色质", "en": "euchromatin", "d": "指间期细胞核内染色质纤维压缩程度低，处于伸展状态，用碱性染料染色时着色浅的染色体。"}, {"ch": "通用", "t": "核仁组织者区", "en": "nucleolair organizing region,NOR", "d": "位于某些染色体的次缢痕处，具有缔合核仁的功能，称为核仁组织者区，即 NOR。"}, {"ch": "通用", "t": "核骨架", "en": "nuclear skeleton", "d": "也称核基质，是间期细胞核内，除去染色质和核仁之外的网架体系和均质物质。其基本形态与细胞质内的细胞骨架相似，且在结构上有一定的联系，因此也称为核骨架。与 DNA 复制和染色体的构建有关。核骨架由3~30um 的蛋白纤维和一些颗粒结构组成，主要成分是蛋白质，还含少量的 RNA 和 DNA。核基质可能参与染色体DNA 的包装和构建、DNA 复制、基因表达以及核内的一系列生物活动。"}, {"ch": "通用", "t": "前胶原", "en": "procollagen", "d": "是指带有前肽的3股螺旋胶原分子。"}, {"ch": "通用", "t": "纤连蛋白", "en": "fibronectin.FN", "d": "是一种大型的糖蛋白，存在于所有脊椎动物。以可溶的形式存在于血浆及各种体液中，以不溶的形式存在于细胞外基质及细胞表面，可将细胞连接到细胞外基质上。"}, {"ch": "通用", "t": "层粘连蛋白", "en": "laminin", "d": "是一种大型的糖蛋白，与 IV 胶原一起构成基膜，是胚胎发育过程中出现最早的细胞外基质成分。"}, {"ch": "通用", "t": "氨基聚糖", "en": "glycosaminoglycan,GAC", "d": "是重复二塘单位构成德无分支长链多糖，二糖单位通常由氨基己糖和糖醛酸组成，但硫酸角质素中糖醛酸由半乳糖代替。"}, {"ch": "通用", "t": "锚定依赖性", "en": "anchorage dependence", "d": "正常真核细胞除成熟血细胞外，大多需黏附于细胞外基质才能抑制凋亡而存活，称为锚定依赖性。"}, {"ch": "通用", "t": "基膜", "en": "basement membrane", "d": "是上皮细胞下方一层柔软的特化的细胞外基质，也存在于肌肉、脂肪和神经膜细胞周围。它不仅起保护和过滤的作用，还决定细胞的极性，影响细胞的代谢、存活、迁移、增殖和分化。"}, {"ch": "通用", "t": "单纯运输", "en": "simple diffusion", "d": "不需要膜运输蛋白帮助，不消耗能量，物质从高浓度到低浓度运输。"}, {"ch": "通用", "t": "帮助运输", "en": "facilitated diffusion", "d": "借助于细胞膜上载体蛋白的构象改变而顺浓度的物质运输方式。"}, {"ch": "通用", "t": "结构性分泌途径", "en": "constitutive pathway of secretion", "d": "分泌蛋白合成后，立即包装入高尔基复合体的分泌泡中，然后迅速带到细胞膜处排出。"}, {"ch": "通用", "t": "调节性分泌途径", "en": "regulated pathway of secretion", "d": "分泌蛋白或小分子合成后，储存在分泌泡中。只有当接受细胞外信号的刺激时，分泌泡才移到细胞膜处，将分泌泡中的物质排出。"}, {"ch": "通用", "t": "信号分子", "en": "signaling molecules", "d": "是指生物体内的某些化学分子，即非营养物，又非能源物质和结构物质，而且也不是酶，它们主要是用来在细胞间和细胞内传递信息，如激素、神经递质、生长因子等统称为信号分子，它们的唯一功能是同细胞受体结合，传递细胞信息。"}, {"ch": "通用", "t": "受体", "en": "receptor", "d": "是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。"}, {"ch": "通用", "t": "离子通道偶联受体", "en": "into-channel linked receptor", "d": "具有离子通道作用的细胞质膜受体称为离子通道受体。"}, {"ch": "通用", "t": "酶联受体", "en": "enzyme linked receptor", "d": "这种受体蛋白即是受体，又是酶。一旦被配体激活既具有酶活性并将信号放大，又称催化受体。酶联受体也是跨膜蛋白，细胞内结构域常常具有某种酶的活性，故称为酶联受体。按照受体的细胞内结构域是否具有酶活性将此类受体分成两大类：缺少细胞内催化活性的酶联受体和具有细胞内催化活性的受体。"}, {"ch": "通用", "t": "信号级联放大", "en": "signaling cascade", "d": "从细胞表面受体接收外部信号到最后作出综合性应答是一个将信号逐步放大的过程，称为信号的次级联放大反应。组成次级联反应的各个成员称为一个级联，主要是由磷酸化和去磷酸化的酶组成。"}, {"ch": "通用", "t": "腺苷酸环化酶", "en": "adenylate cyclase,AC", "d": "是膜整合蛋白，它的 N 端和 C 端都朝向细胞质。腺苷酸环化酶在膜的细胞质面有两个催化结构域，还有两个膜整合区，每个膜整合区分别有6个跨膜的 a 螺旋。哺乳动物中已发现6个腺苷酸环化酶异构体。由于腺苷酸环化酶能够将 ATP 转成 cAMP，引起细胞的信号应答，因此，腺苷酸环化酶是 G 蛋白偶联系统中的效应物。"}, {"ch": "通用", "t": "信号趋异", "en": "divergence", "d": "是指同一种信号与受体作用后在细胞内分成几个不同的信号途径进行传播，最典型的是受体酪氨酸激酶的信号转导。"}, {"ch": "通用", "t": "窜扰", "en": "crosstalk", "d": "是指不同信号传导途径间的相互影响，即通常所说的“相互作用”（interaction）。"}, {"ch": "通用", "t": "受体钝化", "en": "receptor desensitization", "d": "受体对信号分子失去敏感性称为受体钝化，一般是通过对受体的修饰进行钝化的。如肾上激素受体在丝氨酸和苏氨酸残基磷酸化后，则失去对肾上腺素的信号转导作用。分为同源钝化（homologousdesensitization）和异源钝化（heterologousdesensitization）。"}, {"ch": "通用", "t": "受体减量调节", "en": "receptor down-regulation", "d": "通过内吞作用减少质膜中受体量来调节信号传导，称为受体减量调节。"}, {"ch": "通用", "t": "自养生物", "en": "autotroph", "d": "能够通过光合作用，将无机物转化为可被自身利用的有机物的生物，包括含叶绿素的植物和一些有光合作用的细菌。"}, {"ch": "通用", "t": "细胞生物", "en": "cellular respiration", "d": "细胞内特定的细胞器在 O2的参与下，分解各种大分子产生 CO2，同时将分解代谢所释放的能量储存于 ATP 中的过程，称细胞氧化。"}, {"ch": "通用", "t": "氧化磷酸化", "en": "oxidative phosphorylation", "d": "由高能底物水解放能，直接将高能磷酸键从底物转移到 ATP 上，使其磷酸化成为 ATP 的作用。"}, {"ch": "通用", "t": "电子传递呼吸链", "en": "electron transport respiratory chain", "d": "在内膜上有序地排列成相互关联的链状传递电子的酶体系，它们能够可逆地接收和释放 H+和电子。"}, {"ch": "通用", "t": "鬼笔环肽", "en": "phalloidin", "d": "由毒性蘑菇毒蕈产生的一种双环杆肽生物碱，与微丝有强亲和力，使肌动蛋白纤维稳定，抑制解聚，且只与 F-肌动蛋白结合，不与 G-肌动蛋白结合。"}, {"ch": "通用", "t": "驱动蛋白", "en": "kinesin", "d": "与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。"}, {"ch": "通用", "t": "转录", "en": "transcription", "d": "在细胞核中以 DNA 为模板合成 mRNA 的过程，成为转录。"}, {"ch": "通用", "t": "翻译", "en": "translasion", "d": "mRNA 从细胞核进入细胞质，在核糖体上合成蛋白质的过程，称为翻译。"}, {"ch": "通用", "t": "转座子", "en": "transposon", "d": "即移动基因，是指可以从染色体的一个位置转移到另一个位置或在不同染色体之间移动的基因。"}, {"ch": "通用", "t": "重叠基因", "en": "overlapping gene", "d": "是指在同一段 DNA 序列中存在两个基因的核苷酸序列彼此重叠的现象。"}, {"ch": "通用", "t": "基因表达", "en": "gene expression", "d": "DNA 分子中由4种碱基不同组合而构成的遗传信息通过转绿“传抄”给 mRNA，进而 mRNA 通过遗传密码将其翻译成特定蛋白质氨基酸序列的过程，称为基因表达。"}, {"ch": "通用", "t": "遗传密码", "en": "genetic code", "d": "遗传信息由 DNA 通过碱基互补转录至 mRNA 后，mRNA 分子上相邻的3个核苷酸能合成一种氨基酸或是终止信号者称为密码子，所有密码子统称为遗传密码。"}, {"ch": "通用", "t": "引发体", "en": "primosome", "d": "由6种蛋白与 DNA 单链结合所形成的引发前体和引物酶组装而成，能够识别 DNA 复制起点位置。"}, {"ch": "通用", "t": "转录子", "en": "transcription", "d": "DNA 链上从启动子到终止子为止的长度称为一个转录单位，即转录子。"}, {"ch": "通用", "t": "模板链", "en": "template strand", "d": "在 DNA 的两条链中只有其中一条链可作为模板，这条链叫作模板链。又叫作义链。"}, {"ch": "通用", "t": "启动子", "en": "promoter", "d": "转录是从 DNA 模板上的特定部位开始的，这个部位也是 RNA聚合酶结合的部位，称为启动子。"}, {"ch": "通用", "t": "中心法则", "en": "central dogma", "d": "是指细胞内遗传信息的流动方向。遗传信息的流动时从 DNA 转录至 RNA，最后流向蛋白质；同时也包括 mRNA 通过反转录酶形成 DNA 的方式。"}, {"ch": "通用", "t": "细胞增殖", "en": "cell proliferation", "d": "细胞通过生长和分裂获得和母细胞一样遗传特性的子细胞，使细胞数目成倍增加的过程。"}, {"ch": "通用", "t": "细胞增殖周期", "en": "cell generation cycle", "d": "从亲代细胞分裂结束到子代细胞分裂结束之间的间隔时期。"}, {"ch": "通用", "t": "限制点", "en": "restriction point,R 点", "d": "细胞周期中 G1期的特殊调节点，在控制细胞增殖周期起到开和关的“阀门”作用。"}, {"ch": "通用", "t": "有丝分裂促进因子", "en": "mitosis-promoting factor,MPF", "d": "M 期细胞质中存在的异二聚体，由调节细胞进出 M 期所必须的蛋白质激酶和细胞周期蛋白组成，通过促进靶蛋白的磷酸化调节细胞周期。"}, {"ch": "通用", "t": "细胞分裂周期基因", "en": "cell division cycle,cdc", "d": "细胞内的与细胞周期运转和调控有关的基因，产物调节细胞周期的进程。"}, {"ch": "通用", "t": "原癌基因", "en": "proto-oncogene", "d": "正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。"}, {"ch": "通用", "t": "抑癌基因", "en": "tumor suppression oncogene", "d": "正常细胞中存在可抑制恶性增殖的一类基因，产物可以抑制细胞的生长和分裂。"}, {"ch": "通用", "t": "联会", "en": "synapsis", "d": "第1次减数分裂偶线期，同源染色体发生配对现象，称为联会。"}, {"ch": "通用", "t": "四分体", "en": "tetrad", "d": "同源染色体联会的结果是形成二价体，每个二价体都由两条同源染色体组成，这样一个二价体有4条染色单体，称为四分体。"}, {"ch": "通用", "t": "生长因子", "en": "growth factor,GF", "d": "通过与膜上受体相结合诱发一系列生理反应，对细胞的增殖活动进行调节的多肽类物质。"}, {"ch": "通用", "t": "抑素", "en": "chalone", "d": "是一类细胞中产生的对细胞增殖具有抑制作用的调节因子，有些是小分子可溶性蛋白，有些是糖蛋白。"}, {"ch": "通用", "t": "收缩环", "en": "contractile ring", "d": "有丝分裂末期，胞质分裂开始时，大量肌动蛋白和肌球蛋白在细胞膜下聚集形成收缩环。"}, {"ch": "通用", "t": "分裂沟", "en": "cleavage furrow", "d": "收缩环通过微丝滑动、直径逐渐变小、使细胞膜凹陷，产生与纺锤体轴相垂直的分裂沟。"}, {"ch": "通用", "t": "奢侈基因", "en": "luxury gene", "d": "是指与各种分化细胞的特殊性状有直接关系的基因，丧失这类基因对细胞的生存并无直接影响。"}, {"ch": "通用", "t": "同源框基因", "en": "homeobox gene", "d": "凡是含有同源异型基因序列的基因，均称为同源框基因。"}, {"ch": "通用", "t": "细胞诱导", "en": "cell induction", "d": "是指一部分细胞对邻近细胞的形态发生影响，并决定其分化方向的作用。"}, {"ch": "通用", "t": "细胞抑制", "en": "cell inhibition", "d": "是在胚胎发育中，分化的细胞受到邻近细胞产生抑制物质的影响，其作用与诱导相对。"}, {"ch": "通用", "t": "癌基因", "en": "oncogenes", "d": "是控制细胞生长和分裂的正常基因的一种突变形式，能引起正常细胞癌变。"}, {"ch": "通用", "t": "干细胞", "en": "stem cell", "d": "是处于分化过程中仍具有增殖分裂能力，并能分化产生一种以上的“专业”细胞的原始细胞。根据其存在的部位以及分化潜能的大小，将其分为胚胎干细胞和成体干细胞。胚胎干细胞是具有分化成为机体任何一种组织器官潜能的细胞，如囊胚内细胞团中的细胞；成体干细胞是存在于成熟个体各种组织器官中的干细胞，具有自我更新能力，但通常只能分化成为相应或相邻组织器官的专业细胞。"}, {"ch": "通用", "t": "成体干细胞", "en": "adult stem cell", "d": "是在成体组织中具有自我更新能力，能分化产生一种或一种以上组织细胞的未成熟细胞。例如造血干细胞、间充质干细胞、神经干细胞、表皮干细胞、肠干细胞、肝干细胞等。"}, {"ch": "通用", "t": "转分化", "en": "trans-differentiation", "d": "由一种组织类型的干细胞在适当条件下分化为另一种组\f织类型细胞的现象。"}, {"ch": "通用", "t": "不对称分裂", "en": "asymmetry division", "d": "是细胞分裂时产生异型的细胞，如两个子细胞一个是干细胞，而另一个是分化细胞。"}, {"ch": "通用", "t": "过渡放大细胞", "en": "transit amplifying cell", "d": "是介于干细胞和分化细胞之间的过渡细胞，其分裂较快，经若干次分裂后产生分化细胞，起作用是可以通过较少的干细胞产生较多的分化细胞。"}, {"ch": "通用", "t": "衰老", "en": "aging", "d": "又称老化，通常指在正常状况下生物发育成熟后，随年龄增加，自身功能减退，内环境稳定能力与应激能力下降，结构、组分逐步退行性变，趋向死亡的不可逆转的现象。"}];